window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["bc03"]={"id":"bc03","title":"3. 蛋白质的三维结构","sub":"朱圣庚《生物化学》第4版 · 第3章","sub2":"第3章 · 41页老师PPT + 10页AI串讲 + 6页AI图解 + 1页公式 + 1页反应式 + 7页习题精解 + 6页原书页 + 5页原书单图 + 4页过程 + 评估","modules":[{"i":0,"name":"第3章 蛋白质的三维结构（老师PPT精讲+AI补充+习题精解）","slides":[{"sec":"第3章 · 概述","title":"第3章 蛋白质的三维结构","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。本章讲蛋白质三维结构：弱作用力、测定方法、二级结构、纤维蛋白、结构域、球状三级、膜蛋白、四级结构、变性与折叠。对应原书第3章。","img":"assets/img/bc02/full108.jpg","points":["第3章 蛋白质的三维结构","对应老师第5章","七节：概述/方法/二级/纤维/结构域/球状三级/膜蛋白"],"i":0,"check":{"kind":"short","id":"bc03_c0_check","q":"第3章主要研究哪些内容？","a":"蛋白质三维结构概述、测定方法、二级结构、纤维状蛋白、超二级/结构域、球状三级、膜蛋白、四级结构、变性与折叠。","e":"九节主线。","src":"老师PPT·针对性自测"},"imageExplain":"这张图主要在讲：本章讲蛋白质三维结构：弱作用力、测定方法、二级结构、纤维蛋白、结构域、球状三级、膜蛋白、四级结构、变性与折叠。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：第3章 蛋白质的三维结构；对应老师第5章。"},{"sec":"第3章 · AI考点串讲","title":"AI串讲1：三维结构概述","notes":"三维结构由弱相互作用稳定；肽键平面刚性；主链折叠受φ/ψ限制。","points":["弱作用力：氢键、疏水作用、范德华力、离子键；单个弱，集体稳定。","肽键C—N有部分双键性质，六原子共平面；φ/ψ可旋转。","Ramachandran图：允许区/禁区；Gly、Pro特殊。","三级结构=一条链三维折叠；四级=亚基组装。"],"check":{"kind":"short","id":"bc03_ai1_check","q":"稳定蛋白质三维结构的主要作用力有哪些？","a":"氢键、疏水作用、范德华力、离子键；疏水作用常是主要驱动力。","e":"记“弱作用力集体稳定”。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai1_exam","q":"球蛋白折叠的主要驱动力通常是？","o":["A. 疏水作用","B. 肽键","C. 二硫键","D. 磷酸二酯键"],"a":"A","e":"疏水残基埋入内部，减少水化熵损失。","src":"AI补充·选择"},"i":1},{"sec":"第3章 · 一、三维结构概述","title":"稳定三维结构的作用力：总览","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。稳定三维结构主要靠非共价次级键：氢键、疏水作用、范德华力、离子键；二硫键为共价交联。疏水作用通常是三级结构主要驱动力。","img":"assets/img/bc02/full115.jpg","points":["二、稳定蛋白质三维结构的作用力"],"i":2,"exam":{"kind":"mcq","id":"bc03_q19","q":"稳定三级结构的主要作用力通常是？","o":["A. 疏水作用","B. 肽键","C. 磷酸二酯键","D. 糖苷键"],"a":"A","e":"疏水作用是三级结构主要驱动力。","src":"页级选择题"},"imageExplain":"这张图主要在讲：稳定三维结构主要靠非共价次级键：氢键、疏水作用、范德华力、离子键。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：二、稳定蛋白质三维结构的作用力。"},{"sec":"第3章 · 一、三维结构概述","title":"疏水作用（熵效应）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。疏水残基在水环境中趋向内部，减少水化熵损失；这是球状蛋白折叠的主要驱动力。疏水核心使蛋白稳定，亲水残基朝外。","img":"assets/img/bc02/full116.jpg","points":["（三）疏水作用( 熵效应) （四）盐键 （五）二硫键 （一）氢键 （二）范德华力 定向效应 诱导效应 分散效应"],"i":3,"check":{"kind":"short","id":"bc03_c3_check","q":"疏水作用为什么是球状蛋白折叠的主要驱动力？","a":"疏水残基埋入内部，减少水化熵损失；疏水核心稳定三级结构。","e":"熵驱动。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q1","q":"疏水作用的主要驱动力是？","o":["A. 减少水化熵损失","B. 形成肽键","C. 形成二硫键","D. 增加电荷"],"a":"A","e":"疏水残基埋入内部，减少水化熵损失。","src":"页级选择题"},"imageExplain":"这张图主要在讲：疏水残基在水环境中趋向内部，减少水化熵损失。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：（三）疏水作用( 熵效应) （四）盐键 （五）二硫键 （一）氢键 （二）范德华力 定向效应 诱导效应 分散效应。"},{"sec":"第3章 · 一、三维结构概述","title":"多肽主链的折叠","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。肽键具有部分双键性质，六原子共平面；主链只能绕φ/ψ旋转，空间位阻限制可允许构象。","img":"assets/img/bc02/full117.jpg","points":["三、多肽主链折 叠的空间限制 （一）酰胺平面与 α- 碳原子的二面角 （φ 和ψ ）： 规定键两侧基 团为顺式排列时为 0o ，从C 沿键轴方 向观察，顺时针旋 转的角度为正值"],"i":4,"check":{"kind":"short","id":"bc03_c4_check","q":"肽键为什么不能自由旋转？","a":"肽键C—N具有部分双键性质，六原子共平面；主链只绕φ/ψ旋转。","e":"部分双键。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q2","q":"肽键C—N不能自由旋转的主要原因是？","o":["A. 部分双键性质","B. 肽键太长","C. 侧链太大","D. 氢键太弱"],"a":"A","e":"肽键有部分双键性质，六原子共平面。","src":"页级选择题"},"imageExplain":"这张图主要在讲：肽键具有部分双键性质，六原子共平面。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：三、多肽主链折 叠的空间限制 （一）酰胺平面与 α- 碳原子的二面角 （φ 和ψ ）： 规定键两侧基 团为顺式排列时为 0o ，从C 沿键轴方 向观察，顺时针旋 转的角度为正值。"},{"sec":"第3章 · 一、三维结构概述","title":"Ramachandran图：可允许的φ/ψ","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。Ramachandran图以φ/ψ为坐标，显示允许/不允许区；α螺旋、β折叠落在允许区，Gly/Pro特殊。","img":"assets/img/bc02/full118.jpg","points":["（二）可允许的φ 和ψ ：拉氏构象图"],"i":5,"check":{"kind":"short","id":"bc03_c5_check","q":"Ramachandran图以哪两个二面角为坐标？","a":"φ（N—Cα）和ψ（Cα—C）。","e":"φ/ψ。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q3","q":"Ramachandran图的坐标是？","o":["A. φ和ψ","B. pH和pI","C. 分子量和电荷","D. λ和θ"],"a":"A","e":"以主链二面角φ/ψ为坐标。","src":"页级选择题"},"imageExplain":"这张图主要在讲：Ramachandran图以φ/ψ为坐标，显示允许/不允许区。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：（二）可允许的φ 和ψ ：拉氏构象图。"},{"sec":"第3章 · 一、三维结构概述","title":"Ramachandran图：允许区与禁区","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。允许区对应无位阻构象；不允许区因原子碰撞被禁。多数残基落在α/β区，Gly有更大允许范围。","img":"assets/img/bc02/full119.jpg","points":["( 二) 可允许 的φ 和ψ 值：拉氏构 象图 由印度学者 Ramachandran 制 作"],"i":6,"check":{"kind":"short","id":"bc03_c6_check","q":"Ramachandran图的允许区和禁区由什么决定？","a":"主链原子间的空间位阻；允许区无碰撞、能量低，不允许区有碰撞。","e":"空间位阻。","src":"老师PPT·针对性自测"},"imageExplain":"这张图主要在讲：允许区对应无位阻构象。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：( 二) 可允许 的φ 和ψ 值：拉氏构 象图 由印度学者 Ramachandran 制 作。"},{"sec":"第3章 · AI考点串讲","title":"AI串讲2：结构测定方法","notes":"X射线看晶体、NMR看溶液、CD看二级结构、冷冻电镜看大复合物；按样品状态和分辨率选方法。","points":["X射线：晶体、高分辨率、Bragg方程；难长晶体。","NMR：溶液、动态、小到中等蛋白。","CD：快速判断二级结构，低分辨率。","冷冻电镜：大复合物/膜蛋白，近原子分辨率。"],"table":[["方法","样品","优点","局限"],["X射线","晶体","高分辨率","需晶体"],["NMR","溶液","动态/小蛋白","大小限制"],["CD","溶液","快速","低分辨率"],["冷冻电镜","大复合物","近原子","设备/数据处理"]],"tableTitle":"结构测定方法比较","check":{"kind":"short","id":"bc03_ai2_check","q":"X射线、NMR、CD各适合什么样品/信息？","a":"X射线适合晶体高分辨率结构；NMR适合溶液动态中小蛋白；CD快速判断二级结构。","e":"按样品状态和分辨率选。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai2_exam","q":"研究溶液中蛋白质二级结构最常用的快速方法是？","o":["A. CD","B. X射线衍射","C. 冷冻电镜","D. 超速离心"],"a":"A","e":"圆二色性可快速判断α螺旋/β折叠含量。","src":"AI补充·选择"},"i":7},{"sec":"第3章 · 二、结构测定方法","title":"研究蛋白质构象的方法：总览","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。研究构象方法：X射线（晶体）、NMR（溶液/动态）、CD（二级结构）、冷冻电镜（大复合物/膜蛋白）、荧光/超速离心等。","img":"assets/img/bc02/full109.jpg","points":["一、研究蛋白质构象的方法 ( 一)X 射线衍射法"],"i":8,"exam":{"kind":"mcq","id":"bc03_q20","q":"研究蛋白质晶体结构最常用的方法是？","o":["A. X射线衍射","B. CD","C. NMR","D. 超速离心"],"a":"A","e":"X射线衍射解析晶体结构。","src":"页级选择题"},"imageExplain":"这张图主要在讲：研究构象方法：X射线（晶体）、NMR（溶液/动态）、CD（二级结构）、冷冻电镜（大复合物/膜蛋白）、荧光/超速离心等。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：一、研究蛋白质构象的方法 ( 一)X 射线衍射法。"},{"sec":"第3章 · 二、结构测定方法","title":"X射线衍射与Bragg方程","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。X射线衍射用晶体，Bragg方程2d sinθ=nλ；衍射点→电子密度→建模。需解决相位问题。","img":"assets/img/bc02/full110.jpg","points":["基本规律：X 射线穿过原子平面层时，当光程差等于波长的倍 数，反射波可以互相叠加形成衍射斑点","如图5-2 所示，光程 差等于2dsinθ, 上述规律可总结为Bragg 方程： 2dsinθ=nλ(n=±1, ±2, ±3…)"],"check":{"kind":"short","id":"bc03_c9_check","q":"Bragg方程是什么？d代表什么？","a":"2d sinθ=nλ；d为晶面间距，θ为掠射角。","e":"X射线衍射。","src":"老师PPT·针对性自测"},"i":9,"exam":{"kind":"mcq","id":"bc03_q4","q":"X射线衍射解析蛋白质结构通常需要？","o":["A. 晶体","B. 溶液","C. 膜","D. 活细胞"],"a":"A","e":"X射线衍射需要蛋白质晶体。","src":"页级选择题"},"imageExplain":"这张图主要在讲：X射线衍射用晶体，Bragg方程2d sinθ=nλ。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：基本规律：X 射线穿过原子平面层时，当光程差等于波长的倍 数，反射波可以互相叠加形成衍射斑点；如图5-2 所示，光程 差等于2dsinθ, 上述规律可总结为Bragg 方程： 2dsinθ=nλ(n=±1, ±2, ±3…)。"},{"sec":"第3章 · 二、结构测定方法","title":"溶液中蛋白质构象的光谱方法","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。溶液构象方法：CD、荧光、NMR、超速离心等；CD快速判断二级结构，NMR给原子级信息。","img":"assets/img/bc02/full111.jpg","points":["( 二) 研究溶液中蛋白质构象的光谱学方法 1. 紫外差光谱 芳香族氨 基酸在极性环境下 吸收峰向短波长移 动，称作篮移，反 之会红移","2. 荧光和荧光偏振 变性和非 变性蛋白质荧光峰 和荧光偏振的位置 会有特定的变化"],"check":{"kind":"short","id":"bc03_c10_check","q":"CD和NMR分别能提供什么信息？","a":"CD快速判断二级结构；NMR提供溶液中原子的化学位移/NOE等结构约束。","e":"CD二级，NMR原子级。","src":"老师PPT·针对性自测"},"i":10,"exam":{"kind":"mcq","id":"bc03_q21","q":"下列哪项可在溶液中研究构象？","o":["A. CD/NMR","B. 只X射线","C. 只电镜","D. 只测序"],"a":"A","e":"CD/NMR可在溶液中研究构象。","src":"页级选择题"},"imageExplain":"这张图主要在讲：溶液构象方法：CD、荧光、NMR、超速离心等。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：( 二) 研究溶液中蛋白质构象的光谱学方法 1. 紫外差光谱 芳香族氨 基酸在极性环境下 吸收峰向短波长移 动，称作篮移，反 之会红移；2. 荧光和荧光偏振 变性和非 变性蛋白质荧光峰 和荧光偏振的位置 会有特定的变化。"},{"sec":"第3章 · 二、结构测定方法","title":"圆二色性（CD）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。CD是左/右旋圆偏振光吸收差；远紫外反映主链二级结构，近紫外反映芳香族/三级环境。","img":"assets/img/bc02/full112.jpg","points":["3. 圆二色性 由尼科尔棱镜产生 由电光调制器产生"],"i":11,"check":{"kind":"short","id":"bc03_c11_check","q":"CD远紫外区主要反映什么？","a":"主链二级结构（α螺旋、β折叠、无规卷曲）。","e":"远紫外=二级结构。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q5","q":"CD最常用于快速判断？","o":["A. 二级结构","B. 四级结构","C. 二硫键位置","D. 膜蛋白拓扑"],"a":"A","e":"CD可快速判断α螺旋/β折叠含量。","src":"页级选择题"},"imageExplain":"这张图主要在讲：CD是左/右旋圆偏振光吸收差。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：3. 圆二色性 由尼科尔棱镜产生 由电光调制器产生。"},{"sec":"第3章 · 二、结构测定方法","title":"圆二色性的原理","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。CD原理：手性环境使左右旋光吸收不同；α螺旋有特征双负峰，β折叠/无规卷曲谱形不同。","img":"assets/img/bc02/full113.jpg","points":["圆偏振光可看成是相位相差90o 的两个 平面偏振光叠加而成，若左、右圆偏振 光因被测物的吸收而振幅不同，二者叠 加会形成椭圆偏振光","椭圆率θ= 短轴/ 长轴 =tanθ ≈33cl∆ε( 适合于小的θ ， ∆ε= εR− εL ，c 为摩尔浓度，l 为光程，ε 为摩尔吸光系数） 摩尔椭圆率[θ]λ=θ/cl×100=3300 ∆ε"],"check":{"kind":"short","id":"bc03_c12_check","q":"CD为什么能区分不同二级结构？","a":"手性环境使左/右旋圆偏振光吸收不同；不同二级结构有特征CD谱。","e":"左右旋吸收差。","src":"老师PPT·针对性自测"},"i":12,"imageExplain":"这张图主要在讲：CD原理：手性环境使左右旋光吸收不同。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：圆偏振光可看成是相位相差90o 的两个 平面偏振光叠加而成，若左、右圆偏振 光因被测物的吸收而振幅不同，二者叠 加会形成椭圆偏振光；椭圆率θ= 短轴/ 长轴 =tanθ ≈33cl∆ε( 适合于小的θ ， ∆ε= εR− εL ，c 为摩尔浓度，l 为光程，ε 为摩尔吸光系数） 摩尔椭圆率[θ]λ=θ/cl×100=3300 ∆ε。"},{"sec":"第3章 · 二、结构测定方法","title":"核磁共振（NMR）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。NMR在溶液中测结构/动态；需同位素标记，利用化学位移、NOE等约束；适合小到中等蛋白。","img":"assets/img/bc02/full114.jpg","points":["4. 核磁共振(NMR)"],"i":13,"check":{"kind":"short","id":"bc03_c13_check","q":"NMR适合研究什么状态的蛋白质？","a":"溶液状态、小到中等蛋白的结构和动态；常需同位素标记。","e":"溶液/动态。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q6","q":"NMR最适合研究？","o":["A. 溶液中小到中等蛋白","B. 只适合晶体","C. 只适合大复合物","D. 只适合核酸"],"a":"A","e":"NMR研究溶液中蛋白质结构和动态。","src":"页级选择题"},"imageExplain":"这张图主要在讲：NMR在溶液中测结构/动态。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：4. 核磁共振(NMR)。"},{"sec":"第3章 · AI考点串讲","title":"AI串讲3：二级结构","notes":"α螺旋、β折叠、β转角、无规卷曲；氢键模式决定结构。","points":["α螺旋：3.6残基/圈，螺距0.54 nm，i→i+4氢键。","β折叠：平行/反平行，链间氢键，轴心距0.35 nm。","β转角：4个残基，Gly/Pro常见；无规卷曲也有确定构象。","二级结构由主链氢键稳定，侧链决定稳定性/取向。"],"check":{"kind":"short","id":"bc03_ai3_check","q":"α螺旋和β折叠的氢键模式有何不同？","a":"α螺旋是主链i→i+4氢键；β折叠是链间氢键，平行或反平行。","e":"记氢键模式。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai3_exam","q":"α螺旋中每个残基的—NH与哪个残基的—CO形成氢键？","o":["A. 后第4个","B. 前第4个","C. 相邻","D. 侧链"],"a":"A","e":"α螺旋为i→i+4主链氢键。","src":"AI补充·选择"},"i":14},{"sec":"第3章 · 三、二级结构","title":"二级结构：α螺旋","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α螺旋：3.6残基/圈，螺距0.54 nm，i→i+4主链氢键；右手螺旋，侧链朝外。","img":"assets/img/bc02/full120.jpg","points":["四、二级结构：多肽链折叠的规则方式 ( 一)α 螺旋 1.α 螺旋的结构 多肽链中的各个肽平面围绕同一轴旋转，形成 螺旋结构，螺旋一周，沿轴上升的距离即螺距为 0.54nm, 含3.6 个氨基酸残基","两个氨基酸之间的 距离为0.15nm","肽链内形成氢键，氢键的取向几乎与轴平行， 每一个氨基酸残基的酰胺基团的-NH 基与其后第四 个氨基酸残基酰胺基团的-CO 基形成氢键"],"check":{"kind":"short","id":"bc03_c15_check","q":"α螺旋的氢键模式和结构参数是什么？","a":"i→i+4主链氢键；3.6残基/圈，螺距0.54 nm，右手螺旋。","e":"3.6/0.54/i→i+4。","src":"老师PPT·针对性自测"},"i":15,"exam":{"kind":"mcq","id":"bc03_q7","q":"α螺旋的氢键模式是？","o":["A. i→i+4","B. i→i+1","C. 链间","D. 侧链间"],"a":"A","e":"α螺旋为主链i→i+4氢键。","src":"页级选择题"},"imageExplain":"这张图主要在讲：α螺旋：3.6残基/圈，螺距0.54 nm，i→i+4主链氢键。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：四、二级结构：多肽链折叠的规则方式 ( 一)α 螺旋 1.α 螺旋的结构 多肽链中的各个肽平面围绕同一轴旋转，形成 螺旋结构，螺旋一周，沿轴上升的距离即螺距为 0.54nm, 含3.6 个氨基酸残基；两个氨基酸之间的 距离为0.15nm。"},{"sec":"第3章 · 三、二级结构","title":"α螺旋的结构参数","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α螺旋每残基沿轴上升0.15 nm、旋转约100°；n残基长度≈(n/3.6)×0.54 nm。","img":"assets/img/bc02/full121.jpg","points":["每残基上升0.15 nm、旋转约100°。","n残基长度≈(n/3.6)×0.54 nm。","3.6残基/圈，螺距0.54 nm。"],"i":16,"exam":{"kind":"mcq","id":"bc03_q8","q":"α螺旋每圈约含多少个残基？","o":["A. 3.6","B. 2.0","C. 4.0","D. 10"],"a":"A","e":"α螺旋3.6残基/圈，螺距0.54 nm。","src":"页级选择题"},"imageExplain":"这张图主要在讲：α螺旋每残基沿轴上升0.15 nm、旋转约100°。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：每残基上升0.15 nm、旋转约100°。；n残基长度≈(n/3.6)×0.54 nm。。"},{"sec":"第3章 · 三、二级结构","title":"α螺旋结构图","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α螺旋结构图：主链绕中心轴盘绕，氢键平行轴，侧链向外；注意右手性和每圈3.6残基。","img":"assets/img/bc02/full122.jpg","points":["* * 3.613 螺旋"],"i":17,"check":{"kind":"short","id":"bc03_c17_check","q":"α螺旋图中侧链朝哪、氢键方向如何？","a":"侧链朝外；氢键几乎平行于螺旋轴，连接i与i+4。","e":"侧链外、氢键平行轴。","src":"老师PPT·针对性自测"},"imageExplain":"这张图主要在讲：α螺旋结构图：主链绕中心轴盘绕，氢键平行轴，侧链向外。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：* * 3.613 螺旋。"},{"sec":"第3章 · 三、二级结构","title":"α螺旋的偶极矩和帽化","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α螺旋有宏观偶极矩，N端部分正、C端部分负；N端常由带负电残基/帽化稳定。","img":"assets/img/bc02/full123.jpg","points":["2.α 螺旋的偶 极矩和帽化"],"i":18,"check":{"kind":"short","id":"bc03_c18_check","q":"α螺旋的偶极矩方向及帽化作用？","a":"N端部分正、C端部分负；N端帽化/负电荷残基稳定螺旋。","e":"偶极+帽化。","src":"老师PPT·针对性自测"},"imageExplain":"这张图主要在讲：α螺旋有宏观偶极矩，N端部分正、C端部分负。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：2.α 螺旋的偶 极矩和帽化。"},{"sec":"第3章 · 三、二级结构","title":"α螺旋的稳定性","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α螺旋稳定性受氢键、侧链相互作用、螺旋倾向、电荷和Pro/Gly影响；连续Pro中断螺旋。","img":"assets/img/bc02/full124.jpg","points":["3.α 螺旋 的手性"],"i":19,"check":{"kind":"short","id":"bc03_c19_check","q":"哪些因素会降低α螺旋稳定性？","a":"连续Pro/Gly、同种电荷排斥、空间位阻、不利侧链相互作用。","e":"Pro/Gly/电荷。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q23","q":"下列哪种因素不利于α螺旋？","o":["A. 连续Pro","B. 连续Ala","C. 连续Leu","D. 适宜pH"],"a":"A","e":"Pro中断α螺旋。","src":"页级选择题"},"imageExplain":"这张图主要在讲：α螺旋稳定性受氢键、侧链相互作用、螺旋倾向、电荷和Pro/Gly影响。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：3.α 螺旋 的手性。"},{"sec":"第3章 · 三、二级结构","title":"影响α螺旋形成的因素","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。影响α螺旋：Ala/Leu/Glu等倾向高；Pro/Gly破坏；同种电荷/空间位阻不利；环境pH影响带电残基。","img":"assets/img/bc02/full125.jpg","points":["4. 影响α 螺旋形成的因素：R 基太小使键角自由度过大，带同种电荷 的R 基相互靠近，β 碳原子上有分支均不利于形成α 螺旋，含脯氨酸的 肽段不能形成α 螺旋"],"i":20,"check":{"kind":"short","id":"bc03_c20_check","q":"Pro和Gly对α螺旋分别有什么影响？","a":"Pro环状结构中断螺旋；Gly柔性大，降低螺旋倾向。","e":"Pro中断，Gly柔性。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q9","q":"最常中断α螺旋的残基是？","o":["A. Pro","B. Ala","C. Leu","D. Glu"],"a":"A","e":"Pro环状结构使主链弯折，中断螺旋。","src":"页级选择题"},"imageExplain":"这张图主要在讲：影响α螺旋：Ala/Leu/Glu等倾向高。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：4. 影响α 螺旋形成的因素：R 基太小使键角自由度过大，带同种电荷 的R 基相互靠近，β 碳原子上有分支均不利于形成α 螺旋，含脯氨酸的 肽段不能形成α 螺旋。"},{"sec":"第3章 · 三、二级结构","title":"其他类型的螺旋","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。其他螺旋：3₁₀螺旋（3残基/圈）、π螺旋（4.4残基/圈）、左手α螺旋；常见但少于α螺旋。","img":"assets/img/bc02/full126.jpg","points":["5 . 其他类型的螺旋 4.416 螺旋"],"i":21,"check":{"kind":"short","id":"bc03_c21_check","q":"3₁₀螺旋和π螺旋每圈约多少残基？","a":"3₁₀约3残基/圈；π螺旋约4.4残基/圈。","e":"3与4.4。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q22","q":"下列哪种不是常见二级结构？","o":["A. 3₁₀螺旋","B. α螺旋","C. β折叠","D. 肽键"],"a":"A","e":"肽键是化学键，不是二级结构。","src":"页级选择题"},"imageExplain":"这张图主要在讲：其他螺旋：3₁₀螺旋（3残基/圈）、π螺旋（4.4残基/圈）、左手α螺旋。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：5 . 其他类型的螺旋 4.416 螺旋。"},{"sec":"第3章 · 三、二级结构","title":"β折叠片","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。β折叠：肽链伸展、链间氢键；相邻残基轴心距0.35 nm；侧链交替位于片层两侧。","img":"assets/img/bc02/full127.jpg","points":["( 二)β 折叠片 - 折叠是由两条或多条几乎完全伸展的肽链平行排列， 通过链间的氢键交联而形成的","肽链的主链呈锯齿桩折叠构 象","两个氨基酸之间的轴心距为0.35nm"],"check":{"kind":"short","id":"bc03_c22_check","q":"β折叠的链间氢键方向和轴心距？","a":"链间氢键与链长轴接近垂直；相邻残基轴心距约0.35 nm。","e":"垂直/0.35 nm。","src":"老师PPT·针对性自测"},"i":22,"exam":{"kind":"mcq","id":"bc03_q10","q":"β折叠的链间氢键方向通常？","o":["A. 与链长轴接近垂直","B. 与链长轴平行","C. 与侧链平行","D. 无方向"],"a":"A","e":"β折叠链间氢键与链长轴接近垂直。","src":"页级选择题"},"imageExplain":"这张图主要在讲：β折叠：肽链伸展、链间氢键。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：( 二)β 折叠片 - 折叠是由两条或多条几乎完全伸展的肽链平行排列， 通过链间的氢键交联而形成的；肽链的主链呈锯齿桩折叠构 象。"},{"sec":"第3章 · 三、二级结构","title":"平行与反平行β折叠","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。平行β折叠链方向相同，反平行方向相反；反平行氢键更规则，常见于球状蛋白。","img":"assets/img/bc02/full128.jpg","points":["- 折叠有两 种类型","一种 为平行式，即 所有肽链的 N- 端都在同 一边","另一种 为反平行式， 即相邻两条肽 链的方向相反"],"check":{"kind":"short","id":"bc03_c23_check","q":"平行与反平行β折叠的主要区别？","a":"平行链方向相同，反平行方向相反；反平行氢键更规则。","e":"方向/氢键。","src":"老师PPT·针对性自测"},"i":23,"exam":{"kind":"mcq","id":"bc03_q11","q":"平行β折叠的特点是？","o":["A. 链方向相同","B. 链方向相反","C. 无氢键","D. 只含α螺旋"],"a":"A","e":"平行β折叠链方向相同；反平行相反。","src":"页级选择题"},"imageExplain":"这张图主要在讲：平行β折叠链方向相同，反平行方向相反。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：- 折叠有两 种类型；一种 为平行式，即 所有肽链的 N- 端都在同 一边。"},{"sec":"第3章 · 三、二级结构","title":"β折叠结构图（一）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。β折叠结构图一：锯齿状主链、链间氢键、侧链上下交替；注意与α螺旋的氢键方向不同。","img":"assets/img/bc02/full129.jpg","points":["β折叠链间氢键与链轴接近垂直。","相邻残基轴心距0.35 nm。","侧链交替位于片层两侧。"],"i":24,"imageExplain":"这张图主要在讲：β折叠结构图一：锯齿状主链、链间氢键、侧链上下交替。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：β折叠链间氢键与链轴接近垂直。；相邻残基轴心距0.35 nm。。"},{"sec":"第3章 · 三、二级结构","title":"β折叠结构图（二）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。β折叠结构图二：平行/反平行排列与扭曲；β片层可形成β桶/β螺旋等超二级结构。","img":"assets/img/bc02/full130.jpg","points":["平行/反平行β折叠。","β片层可扭曲/形成β桶。","侧链交替。"],"i":25,"imageExplain":"这张图主要在讲：β折叠结构图二：平行/反平行排列与扭曲。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：平行/反平行β折叠。；β片层可扭曲/形成β桶。。"},{"sec":"第3章 · 三、二级结构","title":"β转角和β凸起","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。β转角由4个残基组成，第一个C=O与第四个N—H形成氢键；Gly/Pro常见，使链回折。β凸起是局部不规则。","img":"assets/img/bc02/full131.jpg","points":["( 三)β 转角和β 凸 起 - 转角由四个氨基酸残基组成，弯曲处的第一个氨基酸 残基的 -C=O 和第四个残基的– N-H 之间形成氢键，形 成一个不很稳定的环状结构","这类结构主要存在于球状蛋白分子中"],"check":{"kind":"short","id":"bc03_c26_check","q":"β转角由几个残基组成？哪些残基常见？","a":"4个残基；Gly/Pro常见，第一个C=O与第四个N—H形成氢键。","e":"4残基/Gly/Pro。","src":"老师PPT·针对性自测"},"i":26,"exam":{"kind":"mcq","id":"bc03_q12","q":"β转角通常由几个残基组成？","o":["A. 4","B. 2","C. 8","D. 10"],"a":"A","e":"β转角由4个残基组成，Gly/Pro常见。","src":"页级选择题"},"imageExplain":"这张图主要在讲：β转角由4个残基组成，第一个C=O与第四个N—H形成氢键。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：( 三)β 转角和β 凸 起 - 转角由四个氨基酸残基组成，弯曲处的第一个氨基酸 残基的 -C=O 和第四个残基的– N-H 之间形成氢键，形 成一个不很稳定的环状结构；这类结构主要存在于球状蛋白分子中。"},{"sec":"第3章 · 三、二级结构","title":"无规卷曲","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。无规卷曲没有规则重复的φ/ψ，但仍有确定构象；常位于表面/连接区，参与柔性。","img":"assets/img/bc02/full132.jpg","points":["( 四) 无规卷曲 无一定的规则, 但对一定的球蛋白而言, 特定的区域有 特定的卷曲方式."],"i":27,"check":{"kind":"short","id":"bc03_c27_check","q":"无规卷曲是否没有确定构象？","a":"不是；它没有规则重复的φ/ψ，但仍有确定、较柔性的构象。","e":"有确定构象。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q13","q":"无规卷曲的正确描述是？","o":["A. 仍有确定构象","B. 完全无结构","C. 只含β折叠","D. 只含α螺旋"],"a":"A","e":"无规卷曲也有确定构象，只是不规整。","src":"页级选择题"},"imageExplain":"这张图主要在讲：无规卷曲没有规则重复的φ/ψ，但仍有确定构象。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：( 四) 无规卷曲 无一定的规则, 但对一定的球蛋白而言, 特定的区域有 特定的卷曲方式.。"},{"sec":"第3章 · AI考点串讲","title":"AI串讲4：纤维状蛋白质","notes":"α-角蛋白、丝心蛋白、胶原蛋白、弹性蛋白；结构决定力学性质。","points":["α-角蛋白：α螺旋卷曲螺旋，富含Cys/二硫键。","丝心蛋白：反平行β折叠，Gly-Ala重复。","胶原蛋白：Gly-X-Y三股螺旋，羟脯氨酸/羟赖氨酸。","弹性蛋白：无规/β转角，弹性纤维。"],"table":[["蛋白","二级结构","特点"],["α-角蛋白","α螺旋卷曲螺旋","Cys/二硫键"],["丝心蛋白","反平行β折叠","Gly-Ala重复"],["胶原蛋白","三股螺旋","Gly-X-Y，交联"],["弹性蛋白","无规/β转角","弹性"]],"tableTitle":"纤维状蛋白比较","check":{"kind":"short","id":"bc03_ai4_check","q":"胶原蛋白的氨基酸重复序列和结构特点是什么？","a":"Gly-X-Y重复，三条左手螺旋形成右手三股超螺旋；羟脯氨酸/羟赖氨酸参与稳定和交联。","e":"记Gly-X-Y和三股螺旋。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai4_exam","q":"胶原蛋白的特征重复序列是？","o":["A. Gly-X-Y","B. Gly-Ala","C. Lys-Arg","D. Phe-Trp"],"a":"A","e":"胶原蛋白为(Gly-X-Y)n，Gly占1/3。","src":"AI补充·选择"},"i":28},{"sec":"第3章 · 四、纤维状蛋白质","title":"纤维状蛋白质：总览","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。纤维状蛋白呈长条/纤维，提供结构支撑；包括α-角蛋白、丝心蛋白、胶原蛋白、弹性蛋白等。","img":"assets/img/bc02/full133.jpg","points":["纤维状蛋白长条/纤维。","角蛋白/丝心蛋白/胶原/弹性蛋白。","结构支撑。"],"i":29,"exam":{"kind":"mcq","id":"bc03_q18","q":"下列属于纤维状蛋白的是？","o":["A. 胶原蛋白","B. 血红蛋白","C. 肌红蛋白","D. 溶菌酶"],"a":"A","e":"胶原蛋白是纤维状结构蛋白。","src":"页级选择题"},"imageExplain":"这张图主要在讲：纤维状蛋白呈长条/纤维，提供结构支撑。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：纤维状蛋白长条/纤维。；角蛋白/丝心蛋白/胶原/弹性蛋白。。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"α-角蛋白","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α-角蛋白：α螺旋卷曲螺旋，富含Cys，二硫键交联；皮肤/毛发/角。","img":"assets/img/bc02/full134.jpg","points":["( 一) α- 角蛋白 纤丝"],"i":30,"check":{"kind":"short","id":"bc03_c30_check","q":"α-角蛋白靠什么共价键稳定纤维？","a":"半胱氨酸之间的二硫键；α螺旋形成卷曲螺旋。","e":"二硫键。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q14","q":"α-角蛋白中稳定纤维的主要共价键是？","o":["A. 二硫键","B. 肽键","C. 磷酸二酯键","D. 糖苷键"],"a":"A","e":"α-角蛋白富含Cys，二硫键稳定纤维。","src":"页级选择题"},"imageExplain":"这张图主要在讲：α-角蛋白：α螺旋卷曲螺旋，富含Cys，二硫键交联。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：( 一) α- 角蛋白 纤丝。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"α-角蛋白的原纤维","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α-角蛋白原纤维：两条α螺旋形成卷曲螺旋→protofilament→microfibril；二硫键稳定。","img":"assets/img/bc02/full135.jpg","points":["原纤维 初原纤维 卷曲的螺旋"],"i":31,"check":{"kind":"short","id":"bc03_c31_check","q":"α-角蛋白原纤维的装配层次？","a":"α螺旋→卷曲螺旋→protofilament→microfibril；二硫键稳定。","e":"层次装配。","src":"老师PPT·针对性自测"},"imageExplain":"这张图主要在讲：α-角蛋白原纤维：两条α螺旋形成卷曲螺旋→protofilament→microfibril。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：原纤维 初原纤维 卷曲的螺旋。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"α-角蛋白结构图（一）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α-角蛋白结构图一：卷曲螺旋的七残基重复（heptad）与疏水界面。","img":"assets/img/bc02/full136.jpg","points":["卷曲螺旋七残基重复。","疏水界面稳定。","二硫键。"],"i":32,"imageExplain":"这张图主要在讲：α-角蛋白结构图一：卷曲螺旋的七残基重复（heptad）与疏水界面。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：卷曲螺旋七残基重复。；疏水界面稳定。。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"α-角蛋白结构图（二）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α-角蛋白结构图二：多股卷曲螺旋装配成原纤维。","img":"assets/img/bc02/full137.jpg","points":["多股卷曲螺旋。","原纤维层次。","角蛋白。"],"i":33,"imageExplain":"这张图主要在讲：α-角蛋白结构图二：多股卷曲螺旋装配成原纤维。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：多股卷曲螺旋。；原纤维层次。。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"α-角蛋白结构图（三）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α-角蛋白结构图三：原纤维/微原纤维的层次与二硫键交联。","img":"assets/img/bc02/full138.jpg","points":["原纤维/微原纤维。","二硫键交联。","角蛋白。"],"i":34,"imageExplain":"这张图主要在讲：α-角蛋白结构图三：原纤维/微原纤维的层次与二硫键交联。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：原纤维/微原纤维。；二硫键交联。。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"丝心蛋白和其他β-角蛋白","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。丝心蛋白：反平行β折叠，Gly-Ala重复；小侧链允许片层紧密堆积，纤维强韧。","img":"assets/img/bc02/full139.jpg","points":["( 二) 丝心蛋白和其他β- 角蛋白：β 折叠片蛋白质"],"i":35,"check":{"kind":"short","id":"bc03_c35_check","q":"丝心蛋白的重复序列和二级结构？","a":"Gly-Ala重复；反平行β折叠，小侧链使片层紧密堆积。","e":"Gly-Ala/反平行β。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q15","q":"丝心蛋白的重复序列和结构是？","o":["A. Gly-Ala，反平行β折叠","B. Gly-X-Y，三股螺旋","C. 全是α螺旋","D. 无规卷曲"],"a":"A","e":"丝心蛋白为Gly-Ala重复的反平行β折叠。","src":"页级选择题"},"imageExplain":"这张图主要在讲：丝心蛋白：反平行β折叠，Gly-Ala重复。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：( 二) 丝心蛋白和其他β- 角蛋白：β 折叠片蛋白质。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"丝心蛋白结构图","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。丝心蛋白结构图：反平行β片层沿纤维轴排列，Gly/Ala交替。","img":"assets/img/bc02/full140.jpg","points":["反平行β片层。","Gly-Ala重复。","纤维强韧。"],"i":36,"imageExplain":"这张图主要在讲：丝心蛋白结构图：反平行β片层沿纤维轴排列，Gly/Ala交替。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：反平行β片层。；Gly-Ala重复。。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"胶原蛋白：三股螺旋","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。胶原蛋白：Gly-X-Y重复，三条左手螺旋形成右手三股超螺旋；羟脯氨酸/羟赖氨酸稳定。","img":"assets/img/bc02/full141.jpg","points":["( 三) 胶原蛋白： 胶原蛋白的二级 结构是由三条肽链组成 的三股螺旋，这是一种 右手超螺旋结构","螺距 为8.6nm ，每圈每股包 含30 个残基","其中每 一股螺旋又是一种特殊 的左手螺旋，螺距为 0.95nm ，每一螺圈含 3.3 个残基, 每一残基 沿轴向的距离为 0.29nm"],"check":{"kind":"short","id":"bc03_c37_check","q":"胶原蛋白的重复序列和螺旋结构？","a":"Gly-X-Y重复；三条左手螺旋形成右手三股超螺旋，羟脯氨酸稳定。","e":"Gly-X-Y/三股螺旋。","src":"老师PPT·针对性自测"},"i":37,"exam":{"kind":"mcq","id":"bc03_q16","q":"胶原蛋白的特征重复序列是？","o":["A. Gly-X-Y","B. Gly-Ala","C. Lys-Arg","D. Phe-Trp"],"a":"A","e":"胶原蛋白为(Gly-X-Y)n，Gly占1/3。","src":"页级选择题"},"imageExplain":"这张图主要在讲：胶原蛋白：Gly-X-Y重复，三条左手螺旋形成右手三股超螺旋。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：( 三) 胶原蛋白： 胶原蛋白的二级 结构是由三条肽链组成 的三股螺旋，这是一种 右手超螺旋结构；螺距 为8.6nm ，每圈每股包 含30 个残基。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"原胶原蛋白分子","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。原胶原蛋白：三股螺旋、端肽；分子间交联形成胶原纤维。","img":"assets/img/bc02/full142.jpg","points":["原胶原蛋白分子 在胶原纤维中都 是有规则地按四 分之一错位，首 尾相接，并行排 列组成纤维束","这样通过1 ／4 错位排列便形成 间隔一定的（大 约70nm) 电子 密度区域，而呈 现横纹区带"],"check":{"kind":"short","id":"bc03_c38_check","q":"原胶原分子的结构和交联意义？","a":"三股螺旋+端肽；分子间交联形成胶原纤维，提供强度。","e":"三股螺旋/交联。","src":"老师PPT·针对性自测"},"i":38,"imageExplain":"这张图主要在讲：原胶原蛋白：三股螺旋、端肽。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：原胶原蛋白分子 在胶原纤维中都 是有规则地按四 分之一错位，首 尾相接，并行排 列组成纤维束；这样通过1 ／4 错位排列便形成 间隔一定的（大 约70nm) 电子 密度区域，而呈 现横纹区带。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"胶原蛋白结构图（一）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。胶原蛋白结构图一：三股螺旋的轴向排列与Gly重复。","img":"assets/img/bc02/full143.jpg","points":["三股螺旋。","Gly-X-Y重复。","羟脯氨酸。"],"i":39,"imageExplain":"这张图主要在讲：胶原蛋白结构图一：三股螺旋的轴向排列与Gly重复。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：三股螺旋。；Gly-X-Y重复。。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"胶原蛋白结构图（二）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。胶原蛋白结构图二：原胶原分子组装成纤维。","img":"assets/img/bc02/full144.jpg","points":["原胶原组装。","纤维形成。","交联。"],"i":40,"imageExplain":"这张图主要在讲：胶原蛋白结构图二：原胶原分子组装成纤维。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：原胶原组装。；纤维形成。。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"胶原蛋白的生物学功能","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。胶原蛋白提供机械强度，存在于皮肤/骨/腱/软骨；维生素C参与羟化，缺乏影响交联。","img":"assets/img/bc02/full145.jpg","points":["胶原蛋白属于结构蛋白质，使骨、腱、软骨和皮肤具有机械强度","胶 原蛋白至少包括四种类型，称胶原蛋白I 、Ⅱ、Ⅲ和Ⅳ","腱的胶原纤维具有 很高的抗张强度(tensile strength) ，约为20-30kg ／mm2 ，相当于 12 号冷拉钢丝的拉力"],"check":{"kind":"short","id":"bc03_c41_check","q":"胶原蛋白的主要功能和维生素C的作用？","a":"提供机械强度；维生素C参与脯氨酸/赖氨酸羟化，缺乏影响交联。","e":"结构支撑/维生素C。","src":"老师PPT·针对性自测"},"i":41,"exam":{"kind":"mcq","id":"bc03_q24","q":"胶原蛋白的主要功能是？","o":["A. 结构支撑","B. 运输氧","C. 催化反应","D. 免疫防御"],"a":"A","e":"胶原蛋白为结构蛋白，提供机械强度。","src":"页级选择题"},"imageExplain":"这张图主要在讲：胶原蛋白提供机械强度，存在于皮肤/骨/腱/软骨。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：胶原蛋白属于结构蛋白质，使骨、腱、软骨和皮肤具有机械强度；胶 原蛋白至少包括四种类型，称胶原蛋白I 、Ⅱ、Ⅲ和Ⅳ。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"胶原蛋白的共价交联","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。胶原交联：赖氨酰氧化酶氧化赖氨酸/羟赖氨酸，形成醛基，缩合成交联；随年龄增加。","img":"assets/img/bc02/full146.jpg","points":["赖氨酰氧化酶。","醛基交联。","随年龄增加。"],"i":42,"exam":{"kind":"mcq","id":"bc03_q17","q":"胶原蛋白交联形成的关键氨基酸衍生物是？","o":["A. 羟赖氨酸/赖氨酸","B. 色氨酸","C. 半胱氨酸","D. 组氨酸"],"a":"A","e":"羟赖氨酸参与形成吡啶啉等交联。","src":"页级选择题"},"imageExplain":"这张图主要在讲：胶原交联：赖氨酰氧化酶氧化赖氨酸/羟赖氨酸，形成醛基，缩合成交联。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：赖氨酰氧化酶。；醛基交联。。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"胶原蛋白交联图","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。胶原交联图：分子间/分子内交联，吡啶啉等成熟交联。","img":"assets/img/bc02/full147.jpg","points":["分子间/内交联。","吡啶啉。","组织刚性。"],"i":43,"imageExplain":"这张图主要在讲：胶原交联图：分子间/分子内交联，吡啶啉等成熟交联。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：分子间/内交联。；吡啶啉。。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"吡啶啉交联","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。吡啶啉由原胶原N端与相邻C端形成，是成熟交联；随年龄增多，增加组织刚性。","img":"assets/img/bc02/full148.jpg","points":["吡啶啉是由一个 原胶原的N 末端 区和另一个相邻 的原胶原的C 末 端区之间形成","随着年龄的增长， 胶原蛋白之间的交 联键会增多"],"check":{"kind":"short","id":"bc03_c44_check","q":"吡啶啉交联如何形成？有什么意义？","a":"原胶原N端与相邻C端交联形成；随年龄增多，增加组织刚性。","e":"成熟交联/刚性。","src":"老师PPT·针对性自测"},"i":44,"imageExplain":"这张图主要在讲：吡啶啉由原胶原N端与相邻C端形成，是成熟交联。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：吡啶啉是由一个 原胶原的N 末端 区和另一个相邻 的原胶原的C 末 端区之间形成；随着年龄的增长， 胶原蛋白之间的交 联键会增多。"},{"sec":"第3章 · AI考点串讲","title":"AI串讲5：超二级结构与结构域","notes":"超二级结构是二级结构的组合（βαβ、ββ、αα）；结构域是三级结构中相对独立的折叠区。","points":["常见motif：βαβ、ββ、αα、β转角组合。","结构域：相对独立折叠、常具独立功能/活性位点。","结构域可重组/演化，是蛋白质进化的模块。","例子：免疫球蛋白折叠、EF手、锌指。"],"check":{"kind":"short","id":"bc03_ai5_check","q":"什么是超二级结构和结构域？","a":"超二级结构是相邻二级结构的组合（如βαβ）；结构域是三级结构中相对独立、常具功能的折叠区。","e":"motif vs domain。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai5_exam","q":"“βαβ”属于？","o":["A. 超二级结构","B. 四级结构","C. 膜蛋白","D. 核酸结构"],"a":"A","e":"βαβ是二级结构的组合，属于超二级结构/motif。","src":"AI补充·选择"},"i":45},{"sec":"第3章 · AI考点串讲","title":"AI串讲6：球状蛋白三级结构","notes":"疏水核心+亲水表面；结构域组合；活性位点常在裂隙。","points":["疏水残基埋在内核，亲水残基在表面。","三级结构由弱作用力和二硫键稳定。","球状蛋白常由多个结构域组成。","活性位点常位于结构域之间/表面裂隙。"],"check":{"kind":"short","id":"bc03_ai6_check","q":"球状蛋白三级结构为什么常形成疏水核心？","a":"疏水残基埋入内部可减少水化熵损失，是折叠的主要驱动力；亲水残基朝向表面。","e":"疏水作用驱动。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai6_exam","q":"球状蛋白内部通常富集？","o":["A. 疏水残基","B. 带电残基","C. 糖链","D. 核酸"],"a":"A","e":"疏水核心是球状蛋白稳定因素。","src":"AI补充·选择"},"i":46},{"sec":"第3章 · AI考点串讲","title":"AI串讲7：膜蛋白结构","notes":"膜内在蛋白/膜外周蛋白；跨膜α螺旋或β桶。","points":["膜内在蛋白：跨膜段多为α螺旋，少数β桶。","膜外周蛋白：靠离子键/氢键附着表面。","跨膜段预测：疏水指数/正电荷内规则。","例子：细菌视紫红质（7次跨膜α螺旋）、孔蛋白（β桶）。"],"check":{"kind":"short","id":"bc03_ai7_check","q":"膜内在蛋白的跨膜段通常是什么结构？","a":"多为跨膜α螺旋；孔蛋白等为β桶。","e":"记α螺旋/β桶。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai7_exam","q":"细菌视紫红质的跨膜结构是？","o":["A. 7次跨膜α螺旋","B. β桶","C. 单层β折叠","D. 无跨膜段"],"a":"A","e":"细菌视紫红质为7次跨膜α螺旋。","src":"AI补充·选择"},"i":47},{"sec":"第3章 · AI考点串讲","title":"AI串讲8：四级结构与亚基缔合","notes":"四级结构=亚基的种类、数目和空间排布；亚基间主要靠疏水作用、氢键、离子键，有时二硫键。","points":["四级结构：多个亚基通过非共价键缔合；亚基可相同/不同。","驱动力：疏水作用为主，氢键/离子键提供专一性；二硫键可稳定。","对称性：C4、D2等；同种/异种缔合。","优势：稳定性、遗传经济、活性中心组装、协同/别构。"],"check":{"kind":"short","id":"bc03_ai8_check","q":"四级结构的定义和主要驱动力是什么？","a":"亚基的种类、数目和空间排布；主要驱动力是疏水作用，氢键/离子键提供专一性。","e":"四级=亚基组装。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai8_exam","q":"稳定四级结构的主要驱动力通常是？","o":["A. 疏水作用","B. 肽键","C. 磷酸二酯键","D. 糖苷键"],"a":"A","e":"亚基界面疏水作用为主，氢键/离子键提供专一性。","src":"AI补充·选择"},"i":48},{"sec":"第3章 · AI考点串讲","title":"AI串讲9：蛋白质变性","notes":"变性是物理/化学因素破坏次级键，导致天然构象解体；一级结构不断裂。","points":["变性：生物活性丧失、溶解度降低、黏度增加、侧链暴露。","实质：次级键被破坏，肽键/二硫键通常不断裂，一级结构保留。","变性剂：尿素/盐酸胍（氢键）、SDS（疏水）、热、极端pH、有机溶剂、重金属。","可逆 vs 不可逆；复性是恢复天然构象和活性。"],"check":{"kind":"short","id":"bc03_ai9_check","q":"蛋白质变性的实质是什么？一级结构会破坏吗？","a":"次级键被破坏、天然构象解体；一般不断裂肽键，一级结构保留。","e":"变性≠水解。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai9_exam","q":"蛋白质变性通常不涉及？","o":["A. 肽键断裂","B. 氢键破坏","C. 疏水作用破坏","D. 构象改变"],"a":"A","e":"变性主要破坏次级键，肽键通常保留。","src":"AI补充·选择"},"i":49},{"sec":"第3章 · AI考点串讲","title":"AI串讲9：折叠与结构预测","notes":"Anfinsen：序列决定结构；折叠受分子伴侣、折叠酶和细胞环境影响；预测方法从Chou-Fasman到AlphaFold。","points":["Anfinsen核糖核酸酶实验：变性后去变性剂可复性，说明序列决定结构。","折叠漏斗：多路径、能量下降；分子伴侣防止聚集，PDI/PPI帮助二硫键/脯氨酸异构。","二级结构预测：Chou-Fasman/GOR；三级结构：同源建模/Threading；AlphaFold。","预测需实验验证（CD、NMR、晶体/电镜）。"],"check":{"kind":"short","id":"bc03_ai9b_check","q":"Anfinsen实验说明什么？","a":"蛋白质的氨基酸序列决定其三维结构和活性；变性后可复性。","e":"序列决定结构。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai9b_exam","q":"Anfinsen核糖核酸酶复性实验说明？","o":["A. 序列决定结构","B. 变性必然不可逆","C. 肽键断裂","D. 二硫键不能重建"],"a":"A","e":"变性去除后活性恢复，说明一级序列决定天然构象。","src":"AI补充·选择"},"i":50},{"sec":"第3章 · AI图解","title":"AI图解1：超二级结构与结构域","img":"assets/img/bc03ai/domains.svg","notes":"【图源】AI按原书内容重绘。超二级结构是若干相邻二级结构的组合（βαβ、ββ、αα）；结构域是三级结构中相对独立、常具功能的折叠区。","points":["βαβ：β-α-β组合，常见于核苷酸结合蛋白。","ββ：发夹/β-转角连接；αα：卷曲螺旋/螺旋束。","结构域可独立折叠、重组和演化，是功能模块。","考点：区分motif与domain；例子：Ig折叠、EF手、锌指。"],"check":{"kind":"short","id":"bc03_d1_check","q":"超二级结构和结构域有什么区别？","a":"超二级结构是相邻二级结构的组合；结构域是三级结构中相对独立、常具功能的折叠区。","e":"motif vs domain。","src":"AI图解·自测"},"exam":{"kind":"mcq","id":"bc03_d1_exam","q":"“βαβ”属于？","o":["A. 超二级结构","B. 四级结构","C. 膜蛋白","D. 核酸结构"],"a":"A","e":"βαβ是二级结构的组合，属于超二级结构/motif。","src":"AI图解·选择"},"i":51,"imageExplain":"这张图主要在讲：超二级结构是若干相邻二级结构的组合（βαβ、ββ、αα）。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：βαβ：β-α-β组合，常见于核苷酸结合蛋白。；ββ：发夹/β-转角连接；αα：卷曲螺旋/螺旋束。。"},{"sec":"第3章 · AI图解","title":"AI图解2：球状蛋白三级结构","img":"assets/img/bc03ai/globular.svg","notes":"【图源】AI按原书内容重绘。球状蛋白通常疏水残基埋在内核、亲水残基在表面；结构域组合形成裂隙状活性位点。","points":["疏水核心是折叠主要驱动力；亲水/带电残基朝外。","三级结构由疏水作用、氢键、离子键、范德华力、二硫键稳定。","球状蛋白常含多个结构域，活性位点常在结构域之间/表面裂隙。","考点：疏水核心、结构域、活性位点。"],"check":{"kind":"short","id":"bc03_d2_check","q":"球状蛋白为什么形成疏水核心？","a":"疏水残基埋入内部可减少水化熵损失，是折叠主要驱动力；亲水残基朝向表面。","e":"疏水作用驱动。","src":"AI图解·自测"},"exam":{"kind":"mcq","id":"bc03_d2_exam","q":"球状蛋白内部通常富集？","o":["A. 疏水残基","B. 带电残基","C. 糖链","D. 核酸"],"a":"A","e":"疏水核心是球状蛋白稳定因素。","src":"AI图解·选择"},"i":52,"imageExplain":"这张图主要在讲：球状蛋白通常疏水残基埋在内核、亲水残基在表面。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：疏水核心是折叠主要驱动力；亲水/带电残基朝外。；三级结构由疏水作用、氢键、离子键、范德华力、二硫键稳定。。"},{"sec":"第3章 · AI图解","title":"AI图解3：膜蛋白结构","img":"assets/img/bc03ai/membrane.svg","notes":"【图源】AI按原书内容重绘。膜内在蛋白跨膜段多为α螺旋，少数为β桶；膜外周蛋白靠离子键/氢键附着表面。","points":["膜内在蛋白：7次跨膜α螺旋（细菌视紫红质）或β桶（孔蛋白）。","膜外周蛋白：可溶性球状蛋白，靠静电/氢键结合表面。","跨膜段预测：疏水指数、正电荷内规则。","考点：α螺旋/β桶、内外周蛋白、拓扑。"],"check":{"kind":"short","id":"bc03_d3_check","q":"膜内在蛋白的跨膜段通常是什么结构？","a":"多为跨膜α螺旋，少数为β桶（孔蛋白）；膜外周蛋白靠离子键/氢键附着。","e":"α螺旋/β桶。","src":"AI图解·自测"},"exam":{"kind":"mcq","id":"bc03_d3_exam","q":"孔蛋白的跨膜结构是？","o":["A. β桶","B. 7次跨膜α螺旋","C. 单层α螺旋","D. 无跨膜段"],"a":"A","e":"孔蛋白为β桶结构。","src":"AI图解·选择"},"i":53,"imageExplain":"这张图主要在讲：膜内在蛋白跨膜段多为α螺旋，少数为β桶。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：膜内在蛋白：7次跨膜α螺旋（细菌视紫红质）或β桶（孔蛋白）。；膜外周蛋白：可溶性球状蛋白，靠静电/氢键结合表面。。"},{"sec":"第3章 · AI图解","title":"AI图解4：四级结构与亚基缔合","img":"assets/img/bc03ai/fourlevel.svg","notes":"【图源】AI按原书内容重绘。四级结构是亚基的种类、数目和空间排布；亚基间主要靠疏水作用、氢键、离子键，有时二硫键。","points":["四级结构=亚基组装；亚基可相同/不同。","驱动力：疏水作用为主，氢键/离子键提供专一性。","对称性：C4、D2；同种/异种缔合。","优势：稳定性、遗传经济、活性中心组装、协同/别构。"],"check":{"kind":"short","id":"bc03_d4_check","q":"四级结构的定义和主要驱动力？","a":"亚基种类/数目/空间排布；主要驱动力是疏水作用，氢键/离子键提供专一性。","e":"四级=亚基组装。","src":"AI图解·自测"},"exam":{"kind":"mcq","id":"bc03_d4_exam","q":"稳定四级结构的主要驱动力通常是？","o":["A. 疏水作用","B. 肽键","C. 磷酸二酯键","D. 糖苷键"],"a":"A","e":"亚基界面疏水作用为主。","src":"AI图解·选择"},"i":54,"imageExplain":"这张图主要在讲：四级结构是亚基的种类、数目和空间排布。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：四级结构=亚基组装；亚基可相同/不同。；驱动力：疏水作用为主，氢键/离子键提供专一性。。"},{"sec":"第3章 · AI图解","title":"AI图解5：蛋白质变性与复性","img":"assets/img/bc03ai/denature.svg","notes":"【图源】AI按原书内容重绘。变性是物理/化学因素破坏次级键，天然构象解体；一级结构通常保留；去除变性剂可复性。","points":["变性：活性丧失、溶解度下降、黏度增加、侧链暴露。","实质：次级键破坏；肽键/二硫键通常不断裂，一级结构保留。","变性剂：尿素/盐酸胍、SDS、热、极端pH、有机溶剂、重金属。","复性：去除变性剂恢复天然构象；Anfinsen实验。"],"check":{"kind":"short","id":"bc03_d5_check","q":"蛋白质变性的实质是什么？一级结构会破坏吗？","a":"次级键破坏、天然构象解体；一般不断裂肽键，一级结构保留。","e":"变性≠水解。","src":"AI图解·自测"},"exam":{"kind":"mcq","id":"bc03_d5_exam","q":"蛋白质变性通常不涉及？","o":["A. 肽键断裂","B. 氢键破坏","C. 疏水作用破坏","D. 构象改变"],"a":"A","e":"变性主要破坏次级键，肽键通常保留。","src":"AI图解·选择"},"i":55,"imageExplain":"这张图主要在讲：变性是物理/化学因素破坏次级键，天然构象解体。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：变性：活性丧失、溶解度下降、黏度增加、侧链暴露。；实质：次级键破坏；肽键/二硫键通常不断裂，一级结构保留。。"},{"sec":"第3章 · AI图解","title":"AI图解6：折叠与结构预测","img":"assets/img/bc03ai/folding.svg","notes":"【图源】AI按原书内容重绘。Anfinsen：序列决定结构；折叠经漏斗状能量景观，受分子伴侣/折叠酶辅助；预测从Chou-Fasman到AlphaFold。","points":["Anfinsen：变性核糖核酸酶去除变性剂可复性。","折叠漏斗：多路径、能量下降；分子伴侣防聚集；PDI/PPI辅助。","二级结构预测：Chou-Fasman/GOR；三级：同源建模/Threading；AlphaFold。","预测需实验验证（CD/NMR/晶体/电镜）。"],"check":{"kind":"short","id":"bc03_d6_check","q":"Anfinsen实验说明什么？","a":"氨基酸序列决定三维结构和活性；变性后可复性。","e":"序列决定结构。","src":"AI图解·自测"},"exam":{"kind":"mcq","id":"bc03_d6_exam","q":"Anfinsen核糖核酸酶复性实验说明？","o":["A. 序列决定结构","B. 变性不可逆","C. 肽键断裂","D. 二硫键不能重建"],"a":"A","e":"去除变性剂后活性恢复，说明一级序列决定构象。","src":"AI图解·选择"},"i":56,"imageExplain":"这张图主要在讲：Anfinsen：序列决定结构。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：Anfinsen：变性核糖核酸酶去除变性剂可复性。；折叠漏斗：多路径、能量下降；分子伴侣防聚集；PDI/PPI辅助。。"},{"sec":"第3章 · 公式与方程式","title":"公式与方程式总表","notes":"第3章常用公式：Bragg、螺旋/β几何、折叠热力学、Chou-Fasman；先统一单位再代入。","points":["Bragg：2d sinθ=nλ。","α螺旋：L≈(n/3.6)×0.54 nm；每残基0.15 nm。","β折叠：每残基轴心距0.35 nm。","折叠：ΔG=ΔH−TΔS；ΔS=R lnW。","残基数≈Mr/110；CM/Chou-Fasman为倾向性打分。"],"table":[["公式","用途"],["2d sinθ=nλ","X射线晶面间距"],["L=(n/3.6)×0.54 nm","α螺旋长度"],["0.35 nm/残基","β折叠长度估算"],["ΔG=ΔH−TΔS","折叠稳定性"],["N≈Mr/110","残基数估算"]],"tableTitle":"第3章公式速查","check":{"kind":"short","id":"bc03_f1_check","q":"α螺旋长度公式和β折叠每残基距离？","a":"L≈(n/3.6)×0.54 nm；β折叠约0.35 nm/残基。","e":"记单位。","src":"AI图解·自测"},"exam":{"kind":"mcq","id":"bc03_f1_exam","q":"Bragg方程是？","o":["A. 2d sinθ=nλ","B. ΔG=ΔH−TΔS","C. L=(n/3.6)×0.54","D. A=εcl"],"a":"A","e":"X射线衍射Bragg方程。","src":"AI图解·选择"},"i":57},{"sec":"第3章 · 课后习题精解","title":"精解5：Q3/Q8/Q11","notes":"Q3氢键能量、Q8亚基组成、Q11水环境与螺旋；答案强调“环境竞争”和“界面疏水性”。","points":["Q3：真空中氢键约20 kJ/mol；折叠蛋白中与水竞争，净贡献小（约5 kJ/mol）。","Q8：B四聚体界面比A单体有更多疏水残基，A表面更极性。","Q11：埋藏在非极性内部更易成α螺旋；水环境竞争氢键，降低稳定性。"],"table":[["题","关键点","答案"],["Q3","水竞争氢键","净贡献降低"],["Q8","亚基界面疏水性","B界面更疏水"],["Q11","环境对氢键","非极性内部更易成螺旋"]],"tableTitle":"Q3/Q8/Q11精解","check":{"kind":"short","id":"bc03_ex5_check","q":"为什么蛋白质中氢键的净稳定贡献比真空中低？","a":"折叠蛋白中氢键供体/受体与水竞争，形成/断裂氢键的能量相互抵消，净贡献降低。","e":"水竞争。","src":"AI图解·自测"},"exam":{"kind":"mcq","id":"bc03_ex5_exam","q":"四聚体B比单体A界面更可能富集？","o":["A. 疏水残基","B. 糖链","C. 核酸","D. 磷酸基"],"a":"A","e":"亚基缔合主要由疏水作用驱动。","src":"AI图解·选择"},"i":58},{"sec":"第3章 · 课后习题精解","title":"课后习题索引：第3章15题","notes":"题目来自朱圣庚第4版第3章课后习题；按题型和考点索引，精解见后三页。","points":["1–2 计算题：螺旋长度、α/β比例。","3–9 氢键、Ramachandran、螺旋稳定性。","10 Chou-Fasman预测；11 水环境与螺旋。","12–15 亚基、二硫键、对称性、装配。"],"table":[["题号","题型","考点","精解页"],["1","计算","α螺旋轴长/伸展长度","精解1"],["2","计算","α/β比例","精解1"],["3","简答","氢键能量","精解1"],["4","简答","Ramachandran/手性","精解2"],["5","简答","螺旋形成预测","精解2"],["6","简答","多聚Gly手性","精解2"],["7","计算","折叠热力学","精解1"],["8","简答","亚基组成差异","精解3"],["9","简答","螺旋倾向","精解2"],["10","综合","Chou-Fasman","精解2"],["11","简答","水环境与螺旋","精解2"],["12","综合","酶亚基推断","精解3"],["13","综合","毒素二硫键","精解3"],["14","综合","四聚体对称性","精解3"],["15","综合","多阶段装配","精解3"]],"tableTitle":"第3章课后习题索引","check":{"kind":"short","id":"bc03_ex0_check","q":"第3章课后习题主要分哪几类？","a":"计算（螺旋长度、α/β比例、热力学）、Ramachandran/螺旋稳定性、亚基/二硫键/对称性/装配。","e":"先看题型，再定位考点。","src":"AI补充·自测"},"i":59},{"sec":"第3章 · 课后习题精解","title":"精解1：计算题 Q1/Q2/Q7","notes":"计算题先写公式，再统一单位，最后代数值；注意“轴长”和“完全伸展长度”不同。","points":["Q1：α螺旋每残基上升0.15 nm；完全伸展每残基0.36 nm。","Q2：Mr/110≈残基数；0.15x+0.35(n−x)=长度。","Q7：W=2^200；ΔS=R lnW；ΔG=ΔH−TΔS。"],"table":[["题","步骤","答案"],["Q1","78×0.15 nm；78×0.36 nm","轴长11.7 nm；伸展28.08 nm"],["Q2","240000/110≈2182；0.15x+0.35(2182−x)=506 nm","x≈1289；α螺旋≈59%"],["Q7","W=2^200=1.61×10⁶⁰；ΔS≈−1.15 kJ/(K·mol)；ΔH=−500 kJ/mol","ΔG≈−157 kJ/mol，折叠稳定"]],"tableTitle":"Q1/Q2/Q7精解","check":{"kind":"short","id":"bc03_ex1_check","q":"78个残基的α螺旋轴长和完全伸展长度各是多少？","a":"轴长=78×0.15=11.7 nm；完全伸展=78×0.36=28.08 nm。","e":"分清0.15与0.36 nm。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ex1_exam","q":"78个残基的α螺旋轴长约为？","o":["A. 11.7 nm","B. 28.08 nm","C. 5.4 nm","D. 0.54 nm"],"a":"A","e":"78×0.15 nm=11.7 nm。","src":"AI补充·选择"},"i":60},{"sec":"第3章 · 课后习题精解","title":"精解2：Ramachandran与螺旋稳定性","notes":"Q4看φ/ψ落点；Q9看序列中螺旋促进/破坏残基；Q11看环境对氢键的影响。","points":["Q4：φ=−80°、ψ=+120°→左手螺旋，约3.0残基/圈。","Q9：富含Ala/Leu/Glu等螺旋倾向残基的(a)更易成α螺旋；(b)含Pro/Gly等破坏残基。","Q11：埋藏在非极性内部更易成α螺旋，水环境中氢键竞争削弱稳定性。","Q5/Q6：Pro中断螺旋；Gly对称，多聚Gly左右手能量相当。"],"table":[["题","关键判断","答案"],["Q4","φ/ψ落点","左手螺旋，3.0残基/圈"],["Q9","螺旋倾向残基","(a)更可能成α螺旋"],["Q11","水竞争氢键","非极性内部更易成螺旋"],["Q5/Q6","Pro/Gly特殊","Pro中断；多聚Gly左右手等价"]],"tableTitle":"Q4/Q5/Q6/Q9/Q11精解","check":{"kind":"short","id":"bc03_ex2_check","q":"φ=−80°、ψ=+120°的poly-Gly螺旋手性和每圈残基数？","a":"左手螺旋；约3.0个残基/圈。","e":"φ/ψ决定构象。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ex2_exam","q":"下列哪种残基最容易中断α螺旋？","o":["A. Pro","B. Ala","C. Leu","D. Glu"],"a":"A","e":"Pro环状结构使主链弯折，常中断α螺旋。","src":"AI补充·选择"},"i":61},{"sec":"第3章 · 课后习题精解","title":"精解3：亚基、二硫键与结构推断","notes":"结构推断题先找分子量、亚基数、二硫键和末端标记，再下结论。","points":["Q12：Mr 300k，酸解离100k+50k；β-ME后大组分失活且沉降一峰→亚基/二硫键信息。","Q13：SDS前后分子量变化+FDNB两种N端→两条不同链，链间二硫键，各约13k。","Q14：四聚体对称性C4/D2；同种/异种缔合。","Q15：多阶段装配比一步合成更易控制质量，错误可被分步剔除。"],"table":[["题","关键证据","结论"],["Q12","300k→100k+50k；β-ME","多亚基，二硫键交联"],["Q13","SDS前后；DNP-Gly/Tyr","两条不同链，链间二硫键，各约13k"],["Q14","四聚体","C4或D2对称性"],["Q15","分阶段装配","多阶段更易控制质量"]],"tableTitle":"Q12–Q15精解","check":{"kind":"short","id":"bc03_ex3_check","q":"毒素蛋白β-ME处理前后SDS条带变化，能说明什么？","a":"说明两条不同多肽链通过链间二硫键连接；还原后每条链约13k。","e":"SDS+还原+末端标记联合判断。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ex3_exam","q":"SDS-PAGE中β-巯基乙醇的作用是？","o":["A. 还原二硫键","B. 断裂肽键","C. 增加负电荷","D. 染色"],"a":"A","e":"β-巯基乙醇还原二硫键，使链分开。","src":"AI补充·选择"},"i":62},{"sec":"第3章 · 课后习题精解","title":"精解4：其余题 Q5/Q6/Q10/Q14/Q15","notes":"其余题以“判断依据+结论”为主：螺旋倾向、Gly对称、Chou-Fasman、对称性、装配质量控制。","points":["Q5：Ala/Leu等螺旋倾向残基利成螺旋；Pro中断；Gly柔性；Glu/Lys在pH7带电不利。","Q6：多聚Gly左右手螺旋为对映体，能量相当。","Q10：Chou-Fasman按Pα/Pβ/Pt倾向性打分，滑窗预测，需实验验证。","Q14：四聚体可有C4或D2对称性；同种/异种缔合。","Q15：多阶段装配可分步剔除缺陷，比一步合成更易控制质量。"],"table":[["题","关键依据","结论"],["Q5","螺旋倾向/破坏残基","含Ala/Leu多利；Pro/Gly/带电残基不利"],["Q6","Gly对称","左右手能量相当"],["Q10","Chou-Fasman","按倾向性滑窗预测"],["Q14","四聚体","C4或D2对称"],["Q15","分阶段装配","多阶段更易控制质量"]],"tableTitle":"Q5/Q6/Q10/Q14/Q15要点","check":{"kind":"short","id":"bc03_ex4_check","q":"为什么Pro常中断α螺旋？","a":"Pro为环状亚氨基酸，主链弯折且缺少可形成i→i+4氢键的酰胺H，破坏螺旋。","e":"Pro=螺旋破坏者。","src":"教材课后题·自测"},"exam":{"kind":"mcq","id":"bc03_ex4_exam","q":"多聚甘氨酸的左右手α螺旋稳定性如何？","o":["A. 能量相当","B. 右手远稳定","C. 左手远稳定","D. 不能形成"],"a":"A","e":"Gly无侧链手性，左右手螺旋为对映体，能量相当。","src":"教材课后题·选择"},"i":63},{"sec":"第3章 · 课后习题精解","title":"精解7：Q5/Q6/Q10/Q14/Q15完整步骤","notes":"Q5按pH判断侧链电荷与螺旋倾向；Q6看Gly对称；Q10按Chou-Fasman滑窗；Q14看亚基对称性；Q15比较装配阶段错误剔除。","points":["Q5：Leu/Ala等倾向高→α螺旋；Glu/Lys在pH7带电→电荷排斥不利；Pro中断；pH调到等电附近可恢复螺旋倾向。","Q6：Gly无侧链手性，多聚Gly左右手螺旋为对映体，能量相当。","Q10：查Pα/Pβ/Pt→滑窗打分→连续高分片段；本例4–11 α，14–19 β，20–23 β转角，24–30 β。","Q14：四聚体可有C4或D2；同种/异种缔合；Hb的αβ二聚体不对称，最高对称性C2。","Q15：一步合成错误多；多阶段装配可分步剔除缺陷，最终缺陷复合物频率更低。"],"table":[["题","完整思路","答案"],["Q5","先看pH→侧链电荷；再查螺旋倾向；Pro/Gly破坏","Leu等可成α螺旋；Glu/Lys在pH7带电不利；Pro不形成α螺旋；调pH可改变"],["Q6","Gly无侧链手性→左右手为对映体","左右手螺旋能量相当"],["Q10","Chou-Fasman倾向性表+滑窗+连续片段","α：4–11；β：14–19、24–30；β转角：20–23"],["Q14","四聚体亚基排布/同种异种缔合","C4或D2；Hb最高C2"],["Q15","比较多阶段与一步合成的错误剔除","多阶段装配更易控制质量"]],"tableTitle":"Q5/Q6/Q10/Q14/Q15完整步骤","check":{"kind":"short","id":"bc03_ex7_check","q":"Q5中为什么poly-Glu在pH7不易形成α螺旋？","a":"pH7时Glu侧链羧基带负电，同种电荷排斥，破坏α螺旋；降低pH使羧基质子化后可恢复螺旋倾向。","e":"pH→电荷→螺旋稳定性。","src":"教材课后题·自测"},"exam":{"kind":"mcq","id":"bc03_ex7_exam","q":"多聚甘氨酸的左右手α螺旋稳定性如何？","o":["A. 能量相当","B. 右手远稳定","C. 左手远稳定","D. 不能形成"],"a":"A","e":"Gly无侧链手性，左右手螺旋为对映体，能量相当。","src":"教材课后题·选择"},"i":64},{"sec":"第3章 · 过程版","title":"过程版1：Bragg方程算晶面间距","notes":"Bragg方程：2d sinθ=nλ；先统一单位，再代入。","points":["公式：2d sinθ=nλ。","n=1时d=λ/(2sinθ)。","λ=0.154 nm，θ=10°，d≈0.444 nm。","θ为掠射角，d为晶面间距。"],"check":{"kind":"short","id":"bc03_p1_check","q":"λ=0.154 nm，θ=10°，n=1，求d。","a":"d=0.154/(2×sin10°)≈0.154/0.347≈0.444 nm。","e":"先算sinθ，再代入。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_p1_exam","q":"Bragg方程中d代表？","o":["A. 晶面间距","B. 波长","C. 衍射角","D. 电子密度"],"a":"A","e":"d为晶面间距；λ为波长，θ为掠射角。","src":"AI补充·选择"},"i":65},{"sec":"第3章 · 过程版","title":"过程版2：α螺旋长度与氢键计算","notes":"α螺旋每圈3.6个残基、螺距0.54 nm；长度≈(n/3.6)×0.54 nm。","points":["每圈3.6残基；螺距0.54 nm。","n个残基长度≈(n/3.6)×0.54 nm。","i→i+4氢键稳定螺旋。","例：36残基≈10圈×0.54=5.4 nm。"],"check":{"kind":"short","id":"bc03_p2_check","q":"36个残基的α螺旋约多长？","a":"36/3.6=10圈；10×0.54 nm=5.4 nm。","e":"先算圈数，再乘螺距。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_p2_exam","q":"α螺旋每圈约含多少个残基？","o":["A. 3.6","B. 2.0","C. 4.0","D. 10"],"a":"A","e":"α螺旋3.6残基/圈，螺距0.54 nm。","src":"AI补充·选择"},"i":66},{"sec":"第3章 · 过程版","title":"过程版3：纤维状蛋白识别","notes":"看重复序列、二级结构、交联方式：α-角蛋白/丝心蛋白/胶原蛋白各有指纹。","points":["α-角蛋白：α螺旋卷曲螺旋，Cys/二硫键。","丝心蛋白：反平行β折叠，Gly-Ala重复。","胶原蛋白：Gly-X-Y三股螺旋，羟脯氨酸。","弹性蛋白：无规/β转角，弹性。"],"check":{"kind":"short","id":"bc03_p3_check","q":"Gly-X-Y重复、三股螺旋提示哪种蛋白？","a":"胶原蛋白；Gly占1/3，羟脯氨酸/羟赖氨酸参与稳定。","e":"序列+结构双指纹。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_p3_exam","q":"Gly-Ala重复、反平行β折叠提示？","o":["A. 丝心蛋白","B. 胶原蛋白","C. α-角蛋白","D. 弹性蛋白"],"a":"A","e":"丝心蛋白为Gly-Ala重复的反平行β折叠。","src":"AI补充·选择"},"i":67},{"sec":"第3章 · 过程版","title":"过程版4：结构测定方法选择","notes":"先看样品：晶体→X射线；溶液小蛋白→NMR；二级结构→CD；大复合物/膜蛋白→冷冻电镜。","points":["晶体且需高分辨率→X射线。","溶液、动态、小到中等蛋白→NMR。","快速判断二级结构→CD。","大复合物/膜蛋白→冷冻电镜。","综合验证：CD+NMR/晶体/电镜。"],"check":{"kind":"short","id":"bc03_p4_check","q":"一个难结晶的膜蛋白大复合物，优先选什么方法？","a":"冷冻电镜；可在近天然环境中解析大复合物/膜蛋白结构。","e":"难结晶+大复合物→电镜。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_p4_exam","q":"难结晶的膜蛋白大复合物优先选？","o":["A. 冷冻电镜","B. X射线衍射","C. CD","D. 超速离心"],"a":"A","e":"冷冻电镜适合大复合物和膜蛋白。","src":"AI补充·选择"},"i":68},{"title":"原书页：超二级结构与结构域（p.114）","img":"assets/img/bc03book/domains.png","notes":"原书扫描页。重点看：超二级结构定义、三种主要motif（αα、βαβ、ββ）、结构域定义与四类结构域。","points":["原书图3-31/表3-5：motif与domain。","结构域四类：全α、全β、α/β、α+β。","结构域是独立折叠/功能单位。"],"check":{"kind":"short","id":"bc03_book1_check","q":"原书页中结构域大体分为哪四类？","a":"全α、全β、α/β、α+β四类。","e":"记二级结构种类及排列。","src":"原书页·自测"},"i":69,"imageExplain":"这张图主要在讲：重点看：超二级结构定义、三种主要motif（αα、βαβ、ββ）、结构域定义与四类结构域。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：原书图3-31/表3-5：motif与domain。；结构域四类：全α、全β、α/β、α+β。。"},{"title":"原书页：球状蛋白三级结构（p.118）","img":"assets/img/bc03book/globular.png","notes":"原书扫描页。重点看球状蛋白三级结构特征、疏水核心、活性位点空穴。","points":["多种二级结构元件；紧密球状/椭球。","疏水侧链埋内，亲水侧链朝外。","表面空穴常为活性位点。"],"check":{"kind":"short","id":"bc03_book2_check","q":"球状蛋白三级结构有哪些特征？","a":"含多种二级结构、紧密球状、疏水核心、表面活性位点空穴。","e":"四条特征。","src":"原书页·自测"},"i":70,"imageExplain":"这张图主要在讲：重点看球状蛋白三级结构特征、疏水核心、活性位点空穴。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：多种二级结构元件；紧密球状/椭球。；疏水侧链埋内，亲水侧链朝外。。"},{"title":"原书页：膜蛋白结构（p.125）","img":"assets/img/bc03book/membrane.png","notes":"原书扫描页。重点看膜周边/膜内在蛋白分类、单跨膜与7次跨膜、β桶。","points":["膜周边蛋白：靠静电/氢键附着。","膜内在蛋白：单跨膜或7次跨膜α螺旋。","孔蛋白等为β桶。"],"check":{"kind":"short","id":"bc03_book3_check","q":"膜内在蛋白的两种常见跨膜结构？","a":"单次/多次跨膜α螺旋；孔蛋白为β桶。","e":"α螺旋/β桶。","src":"原书页·自测"},"i":71,"imageExplain":"这张图主要在讲：重点看膜周边/膜内在蛋白分类、单跨膜与7次跨膜、β桶。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：膜周边蛋白：靠静电/氢键附着。；膜内在蛋白：单跨膜或7次跨膜α螺旋。。"},{"title":"原书页：四级结构与对称性（p.129）","img":"assets/img/bc03book/fourlevel.png","notes":"原书扫描页。重点看四级结构定义、亚基缔合驱动力、对称性（C4/D2等）。","points":["四级=亚基种类/数目/空间排布。","疏水作用驱动，氢键/离子键提供专一性。","对称性：C4、D2等；同种/异种缔合。"],"check":{"kind":"short","id":"bc03_book4_check","q":"四级结构的主要驱动力和对称性例子？","a":"疏水作用为主；对称性如C4、D2。","e":"亚基组装。","src":"原书页·自测"},"i":72,"imageExplain":"这张图主要在讲：重点看四级结构定义、亚基缔合驱动力、对称性（C4/D2等）。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：四级=亚基种类/数目/空间排布。；疏水作用驱动，氢键/离子键提供专一性。。"},{"title":"原书页：蛋白质变性（p.135）","img":"assets/img/bc03book/denature.png","notes":"原书扫描页。重点看变性定义、实质、现象、变性剂（尿素/SDS）和吴宪学说。","points":["变性：活性丧失、溶解度降低、构象解体。","实质：次级键破坏；一级结构保留。","变性剂：尿素/盐酸胍、SDS、热、极端pH。"],"check":{"kind":"short","id":"bc03_book5_check","q":"蛋白质变性的实质是什么？","a":"次级键被破坏，天然构象解体；肽键/一级结构通常保留。","e":"变性≠水解。","src":"原书页·自测"},"i":73,"imageExplain":"这张图主要在讲：重点看变性定义、实质、现象、变性剂（尿素/SDS）和吴宪学说。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：变性：活性丧失、溶解度降低、构象解体。；实质：次级键破坏；一级结构保留。。"},{"title":"原书页：Anfinsen复性实验（p.137）","img":"assets/img/bc03book/anfinsen.png","notes":"原书扫描页。重点看核糖核酸酶变性/复性、二硫键重建、序列决定结构。","points":["变性RNase（二硫键还原）失去活性。","去除变性剂/氧化后活性恢复。","说明一级序列决定天然构象。"],"check":{"kind":"short","id":"bc03_book6_check","q":"Anfinsen实验说明什么？","a":"蛋白质氨基酸序列决定其三维结构和活性；变性可复性。","e":"序列决定结构。","src":"原书页·自测"},"i":74,"imageExplain":"这张图主要在讲：重点看核糖核酸酶变性/复性、二硫键重建、序列决定结构。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：变性RNase（二硫键还原）失去活性。；去除变性剂/氧化后活性恢复。。"},{"title":"原书单图：超二级结构（图3-31）","img":"assets/img/bc03book/fig-domains.png","notes":"原书图3-31的单图裁切。看βαβ、ββ、αα等motif的二级结构组合方式；注意N/C端方向。","points":["motif=相邻二级结构的组合。","βαβ、ββ、αα是常见类型。","motif是三级结构的构件。"],"check":{"kind":"short","id":"bc03_fig1_check","q":"原书图3-31展示了哪些超二级结构？","a":"βαβ、ββ、αα等二级结构组合（motif）。","e":"看图记类型。","src":"原书单图·自测"},"exam":{"kind":"mcq","id":"bc03_fig1_exam","q":"“βαβ”属于？","o":["A. 超二级结构","B. 四级结构","C. 膜蛋白","D. 核酸"],"a":"A","e":"βαβ是二级结构组合，属于motif。","src":"原书单图·选择"},"i":75,"imageExplain":"这张图主要在讲：看βαβ、ββ、αα等motif的二级结构组合方式。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：motif=相邻二级结构的组合。；βαβ、ββ、αα是常见类型。。"},{"title":"原书单图：溶菌酶三级结构（图3-38）","img":"assets/img/bc03book/fig-globular.png","notes":"原书图3-38的单图裁切。看溶菌酶中α螺旋、β折叠、β转角、无规卷曲如何组合成球状三级结构。","points":["球状蛋白含多种二级结构元件。","疏水核心、亲水表面。","活性位点位于表面裂隙。"],"check":{"kind":"short","id":"bc03_fig2_check","q":"溶菌酶图中可见哪些二级结构？","a":"α螺旋、β折叠、β转角、无规卷曲。","e":"多种元件组合。","src":"原书单图·自测"},"exam":{"kind":"mcq","id":"bc03_fig2_exam","q":"球状蛋白内部通常富集？","o":["A. 疏水残基","B. 带电残基","C. 糖链","D. 核酸"],"a":"A","e":"疏水核心稳定三级结构。","src":"原书单图·选择"},"i":76,"imageExplain":"这张图主要在讲：看溶菌酶中α螺旋、β折叠、β转角、无规卷曲如何组合成球状三级结构。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：球状蛋白含多种二级结构元件。；疏水核心、亲水表面。。"},{"title":"原书单图：血型糖蛋白A跨膜（图3-46）","img":"assets/img/bc03book/fig-membrane.png","notes":"原书图3-46的单图裁切。看单次跨膜α螺旋、膜内外两侧结构域和糖链。","points":["单跨膜α螺旋锚定膜。","大部分蛋白位于膜一侧/两侧水环境。","膜外结构域可带糖链。"],"check":{"kind":"short","id":"bc03_fig3_check","q":"血型糖蛋白A的跨膜结构是什么？","a":"单次跨膜α螺旋；大部分位于膜外，带糖链。","e":"单跨膜。","src":"原书单图·自测"},"exam":{"kind":"mcq","id":"bc03_fig3_exam","q":"血型糖蛋白A属于？","o":["A. 单次跨膜蛋白","B. 7次跨膜蛋白","C. β桶","D. 膜外周蛋白"],"a":"A","e":"血型糖蛋白A为单次跨膜α螺旋。","src":"原书单图·选择"},"i":77,"imageExplain":"这张图主要在讲：看单次跨膜α螺旋、膜内外两侧结构域和糖链。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：单跨膜α螺旋锚定膜。；大部分蛋白位于膜一侧/两侧水环境。。"},{"title":"原书单图：尿素/盐酸胍变性","img":"assets/img/bc03book/fig-denature.png","notes":"原书变性示意图的单图裁切。看尿素/盐酸胍与主链竞争氢键，破坏次级键，使天然构象解体。","points":["尿素/盐酸胍竞争氢键。","SDS破坏疏水作用。","变性通常不破坏肽键。"],"check":{"kind":"short","id":"bc03_fig4_check","q":"尿素和盐酸胍主要破坏哪类作用力？","a":"与主链竞争氢键，破坏次级键，使构象解体。","e":"氢键竞争。","src":"原书单图·自测"},"exam":{"kind":"mcq","id":"bc03_fig4_exam","q":"SDS主要破坏？","o":["A. 疏水作用","B. 肽键","C. 二硫键","D. 磷酸二酯键"],"a":"A","e":"SDS破坏疏水相互作用，使蛋白变性。","src":"原书单图·选择"},"i":78,"imageExplain":"这张图主要在讲：原书变性示意图的单图裁切。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：尿素/盐酸胍竞争氢键。；SDS破坏疏水作用。。"},{"title":"原书单图：RNase复性（图3-57）","img":"assets/img/bc03book/fig-anfinsen.png","notes":"原书图3-57的单图裁切。看β-巯基乙醇还原二硫键、尿素变性，去除后氧化复性、活性恢复。","points":["β-巯基乙醇还原二硫键。","尿素破坏次级键。","去除变性剂后复性，说明序列决定结构。"],"check":{"kind":"short","id":"bc03_fig5_check","q":"Anfinsen实验中β-巯基乙醇和尿素各起什么作用？","a":"β-巯基乙醇还原二硫键；尿素破坏氢键/次级键。去除后可复性。","e":"还原+变性。","src":"原书单图·自测"},"exam":{"kind":"mcq","id":"bc03_fig5_exam","q":"Anfinsen实验说明？","o":["A. 序列决定结构","B. 变性不可逆","C. 肽键断裂","D. 二硫键不能重建"],"a":"A","e":"复性后活性恢复，说明一级序列决定天然构象。","src":"原书单图·选择"},"i":79,"imageExplain":"这张图主要在讲：看β-巯基乙醇还原二硫键、尿素变性，去除后氧化复性、活性恢复。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：β-巯基乙醇还原二硫键。；尿素破坏次级键。。"},{"sec":"第3章 · 反应式速查","title":"第3章相关反应式速查","notes":"第3章反应式少：重点是二硫键氧化/还原、胶原交联；肽键形成/水解在bc02已学。","points":["二硫键氧化：2 Cys-SH ⇌ Cys-S-S-Cys + 2H⁺ + 2e⁻；还原反向。","DTT/β-巯基乙醇还原二硫键；过甲酸氧化断键。","胶原交联：赖氨酰氧化酶把Lys/Hyl的—NH₂氧化成醛基，再缩合成吡啶啉等。","肽键形成脱H₂O，水解加H₂O；变性不是化学反应式。"],"table":[["反应","条件/意义"],["2 Cys-SH ⇌ Cys-S-S-Cys + 2H⁺ + 2e⁻","氧化成键/还原断键；稳定三级/四级结构"],["Lys/Hyl—NH₂ → 醛基（赖氨酰氧化酶）","胶原交联第一步；维生素C参与羟化"],["醛基 + Lys/Hyl—NH₂ → 吡啶啉等","成熟交联，增加组织刚性"],["氨基酸 + 氨基酸 → 肽 + H₂O","肽键形成；水解为逆向"]],"tableTitle":"第3章相关反应式","check":{"kind":"short","id":"bc03_r1_check","q":"写出二硫键氧化成键的反应式。","a":"2 Cys-SH ⇌ Cys-S-S-Cys + 2H⁺ + 2e⁻；还原剂可使其逆向。","e":"氧化成键、还原断键。","src":"反应式·自测"},"exam":{"kind":"mcq","id":"bc03_r1_exam","q":"二硫键氧化成键时脱去？","o":["A. 2H⁺和2e⁻","B. H₂O","C. CO₂","D. NH₃"],"a":"A","e":"两个—SH氧化脱2H⁺和2e⁻形成S—S。","src":"反应式·选择"},"i":80},{"sec":"第3章 · 使用评估","title":"bc03 使用评估与学习建议","notes":"本页评估基于当前网页版：bc03 已按原书第3章重建，老师第5章原图+AI串讲+过程版+题库。","points":["覆盖：原书第3章九节，含四级结构、变性/折叠/预测、课后习题。","强项：41页notes重写+6页原书页+5页原书单图+6页AI图解+公式+7页习题精解。","短板：部分原书图仍需对照整页；下载版需重新生成。","适合：第3章自学/复习/考研基础题。","新增：第3章相关反应式速查（二硫键/胶原交联/肽键）。"],"table":[["维度","评价"],["内容覆盖","原书第3章九节基本覆盖"],["讲解/过程","41页notes+原书页/单图+AI图解+公式"],["题库","章测43题+7页习题精解+页级51题"],["视觉","原书页+单图+AI图解，图源已标注"],["综合评分","约 90 分"]],"tableTitle":"bc03 当前评估","i":81}]}],"mcq":[{"id":"bc03_exam_mcq1","modI":0,"q":"α螺旋中i位残基的—NH主要与哪个残基的—CO形成氢键？","o":["A. i+4","B. i+1","C. i−4","D. 侧链"],"a":"A","e":"α螺旋为主链i→i+4氢键。","kp":""},{"id":"bc03_exam_mcq2","modI":0,"q":"β折叠的链间氢键方向通常？","o":["A. 与链长轴接近垂直","B. 与链长轴平行","C. 与侧链平行","D. 无方向"],"a":"A","e":"β折叠链间氢键与链长轴接近垂直。","kp":""},{"id":"bc03_exam_mcq3","modI":0,"q":"胶原蛋白的特征重复序列是？","o":["A. Gly-X-Y","B. Gly-Ala","C. Lys-Arg","D. Phe-Trp"],"a":"A","e":"胶原蛋白为(Gly-X-Y)n，Gly占1/3。","kp":""},{"id":"bc03_exam_mcq4","modI":0,"q":"研究溶液中蛋白质二级结构最常用的快速方法是？","o":["A. CD","B. X射线衍射","C. 冷冻电镜","D. 超速离心"],"a":"A","e":"圆二色性可快速判断α螺旋/β折叠含量。","kp":""},{"id":"bc03_exam_mcq5","modI":0,"q":"X射线衍射解析蛋白质结构通常需要？","o":["A. 晶体","B. 溶液","C. 膜","D. 活细胞"],"a":"A","e":"X射线衍射需要蛋白质晶体。","kp":""},{"id":"bc03_exam_mcq6","modI":0,"q":"“βαβ”属于？","o":["A. 超二级结构","B. 四级结构","C. 膜蛋白","D. 核酸结构"],"a":"A","e":"βαβ是二级结构的组合，属于超二级结构/motif。","kp":""},{"id":"bc03_exam_mcq7","modI":0,"q":"细菌视紫红质的跨膜结构是？","o":["A. 7次跨膜α螺旋","B. β桶","C. 单层β折叠","D. 无跨膜段"],"a":"A","e":"细菌视紫红质为7次跨膜α螺旋。","kp":""},{"id":"bc03_exam_mcq8","modI":0,"q":"球状蛋白内部通常富集？","o":["A. 疏水残基","B. 带电残基","C. 糖链","D. 核酸"],"a":"A","e":"疏水核心是球状蛋白稳定因素。","kp":""}],"judge":[{"id":"bc03_exam_judge1","modI":0,"q":"肽键的C—N键可以完全自由旋转。","a":"错","e":"肽键有部分双键性质，六原子共平面，不能自由旋转。","kp":""},{"id":"bc03_exam_judge2","modI":0,"q":"疏水作用通常是球状蛋白折叠的主要驱动力。","a":"对","e":"疏水残基埋入内部，减少水化熵损失。","kp":""},{"id":"bc03_exam_judge3","modI":0,"q":"α螺旋的螺距约为0.54 nm。","a":"对","e":"α螺旋3.6残基/圈，螺距0.54 nm。","kp":""},{"id":"bc03_exam_judge4","modI":0,"q":"胶原蛋白的Gly-X-Y重复中Gly约占1/3。","a":"对","e":"胶原蛋白Gly占残基总数1/3。","kp":""},{"id":"bc03_exam_judge5","modI":0,"q":"CD可以测定蛋白质的高分辨率三维结构。","a":"错","e":"CD只能快速判断二级结构，不能给高分辨率三维结构。","kp":""}],"fill":[{"id":"bc03_exam_fill1","modI":0,"q":"α螺旋每圈约含______个氨基酸残基。","a":"3.6","e":"α螺旋3.6残基/圈，螺距0.54 nm。","kp":""},{"id":"bc03_exam_fill2","modI":0,"q":"α螺旋的螺距约为______ nm。","a":"0.54","e":"α螺旋螺距0.54 nm。","kp":""},{"id":"bc03_exam_fill3","modI":0,"q":"β折叠中相邻氨基酸的轴心距约为______ nm。","a":"0.35","e":"β折叠轴心距0.35 nm。","kp":""},{"id":"bc03_exam_fill4","modI":0,"q":"胶原蛋白的特征重复序列是______。","a":"Gly-X-Y","e":"胶原蛋白为(Gly-X-Y)n。","kp":""},{"id":"bc03_exam_fill5","modI":0,"q":"Bragg方程为______。","a":"2dsinθ=nλ","e":"X射线衍射的Bragg方程。","kp":""}],"short":[{"id":"bc03_short1","modI":0,"q":"稳定蛋白质三维结构的作用力有哪些？","a":"氢键、疏水作用、范德华力、离子键；疏水作用常是主要驱动力。","kps":"每点1分","src":"教材","e":"弱作用力集体稳定；疏水作用驱动折叠。"},{"id":"bc03_short2","modI":0,"q":"肽键为什么具有平面刚性？","a":"肽键C—N具有部分双键性质，六个原子共平面，C—N不能自由旋转；φ/ψ可旋转。","kps":"部分双键+共平面","src":"教材","e":"共振使C—N有双键性。"},{"id":"bc03_short3","modI":0,"q":"Ramachandran图说明什么？","a":"以φ/ψ为坐标，显示主链可允许/不允许的构象区；Gly、Pro特殊。","kps":"φ/ψ+允许区+特殊残基","src":"教材","e":"空间位阻限制主链折叠。"},{"id":"bc03_short4","modI":0,"q":"α螺旋的结构参数有哪些？","a":"3.6残基/圈，螺距0.54 nm，i→i+4主链氢键，右手螺旋。","kps":"3.6/0.54/i→i+4","src":"教材","e":"记参数。"},{"id":"bc03_short5","modI":0,"q":"平行与反平行β折叠有什么区别？","a":"平行β折叠链方向相同，反平行方向相反；两者链间氢键模式/重复距离不同。","kps":"方向+氢键","src":"教材","e":"反平行更常见于球状蛋白。"},{"id":"bc03_short6","modI":0,"q":"胶原蛋白的结构特点是什么？","a":"Gly-X-Y重复，三条左手螺旋形成右手三股超螺旋；羟脯氨酸/羟赖氨酸参与稳定和交联。","kps":"Gly-X-Y+三股螺旋","src":"教材","e":"胶原蛋白为结构蛋白。"},{"id":"bc03_short7","modI":0,"q":"什么是结构域？","a":"三级结构中相对独立、常具独立功能/活性位点的折叠区；可重组/演化。","kps":"独立折叠+功能","src":"教材","e":"domain vs motif。"},{"id":"bc03_short8","modI":0,"q":"膜内在蛋白的跨膜段通常是什么结构？","a":"多为跨膜α螺旋，少数为β桶；膜外周蛋白靠离子键/氢键附着表面。","kps":"α螺旋/β桶","src":"教材","e":"细菌视紫红质7次跨膜α螺旋；孔蛋白β桶。"},{"id":"bc03_short9","modI":0,"q":"φ=−80°、ψ=+120°的poly-Gly螺旋手性和每圈残基数？","a":"左手螺旋；约3.0个残基/圈。","kps":"手性+残基/圈","src":"教材课后题","e":"根据Ramachandran图判断。"},{"id":"bc03_short10","modI":0,"q":"肽(a) LKAENDEAARAMSEA 与(b) CRAGGFPWDQPGTSN，哪个更可能形成α螺旋？为什么？","a":"(a)更可能；含较多螺旋倾向残基；(b)含Pro/Gly等破坏螺旋的残基。","kps":"螺旋倾向+破坏残基","src":"教材课后题","e":"Pro中断螺旋。"},{"id":"bc03_short11","modI":0,"q":"毒素蛋白β-ME处理前后SDS条带变化，能说明什么？","a":"两条不同多肽链通过链间二硫键连接；还原后每条链约13k。","kps":"二硫键+两条链","src":"教材课后题","e":"SDS+还原+末端标记。"},{"id":"bc03_short12","modI":0,"q":"为什么蛋白质中氢键的净稳定贡献比真空中低？","a":"折叠蛋白中氢键供体/受体与水竞争，形成/断裂氢键能量相互抵消，净贡献降低。","kps":"水竞争","src":"教材课后题","e":"环境竞争。"},{"id":"bc03_short13","modI":0,"q":"四聚体B与单体A相比，亚基界面氨基酸组成可能有什么差别？","a":"B的亚基界面富集疏水残基，A表面更极性；疏水作用驱动四聚体缔合。","kps":"界面疏水","src":"教材课后题","e":"亚基缔合驱动力。"},{"id":"bc03_short14","modI":0,"q":"为什么埋藏在非极性内部的多肽片段更易形成α螺旋？","a":"水环境竞争氢键，非极性内部减少竞争，螺旋氢键更稳定。","kps":"水竞争+内部环境","src":"教材课后题","e":"环境对氢键的影响。"}],"calc":[{"id":"bc03_exam_calc1","modI":0,"q":"λ=0.154 nm，θ=10°，n=1，求晶面间距d。","a":"d=0.154/(2sin10°)≈0.444 nm。","e":"Bragg方程2d sinθ=nλ。","kp":""},{"id":"bc03_exam_calc2","modI":0,"q":"36个残基的α螺旋约多长？","a":"36/3.6=10圈；10×0.54 nm=5.4 nm。","e":"长度≈(n/3.6)×0.54 nm。","kp":""},{"id":"bc03_exam_calc3","modI":0,"q":"一个难结晶的膜蛋白大复合物，选择哪种结构测定方法？说明理由。","a":"冷冻电镜；适合大复合物/膜蛋白，可在近天然环境解析，避免长晶体。","e":"方法选择看样品状态和分辨率。","kp":""},{"id":"bc03_exam_calc4","modI":0,"q":"某纤维蛋白富含Gly-X-Y重复并形成三股螺旋，判断它是什么蛋白并说明依据。","a":"胶原蛋白；Gly-X-Y重复、Gly占1/3、三股螺旋、羟脯氨酸/羟赖氨酸交联。","e":"序列+结构双指纹。","kp":""},{"id":"bc03_exam_calc5","modI":0,"q":"78个残基的α螺旋轴长和完全伸展长度各是多少？","a":"轴长=78×0.15=11.7 nm；完全伸展=78×0.36=28.08 nm。","e":"分清每残基上升0.15 nm与伸展0.36 nm。","kp":""},{"id":"bc03_exam_calc6","modI":0,"q":"某蛋白Mr=240000，肽链长506 nm，α螺旋每残基0.15 nm、β折叠每残基0.35 nm，求α螺旋比例。","a":"残基数≈2182；0.15x+0.35(2182−x)=506；x≈1289；比例≈59%。","e":"先算残基数，再解方程。","kp":""}],"term":[{"id":"bc03_exam_term1","modI":0,"term":"疏水作用","def":"非极性基团避开水、聚集在内部，减少水化熵损失的作用；是球状蛋白折叠的主要驱动力。","kps":"非极性+避水+熵","kp":""},{"id":"bc03_exam_term2","modI":0,"term":"Ramachandran图","def":"以主链二面角φ/ψ为坐标，显示蛋白质主链可允许和不允许构象区的图。","kps":"φ/ψ+允许区","kp":""},{"id":"bc03_exam_term3","modI":0,"term":"结构域","def":"三级结构中相对独立、常具独立功能的折叠区，可重组和演化。","kps":"独立折叠+功能","kp":""},{"id":"bc03_exam_term4","modI":0,"term":"卷曲螺旋","def":"两条或多条α螺旋相互缠绕形成的超二级结构，α-角蛋白中常见。","kps":"α螺旋+缠绕","kp":""},{"id":"bc03_exam_term5","modI":0,"term":"β桶","def":"由β折叠片卷成筒状的结构，常见于孔蛋白和膜蛋白。","kps":"β折叠+筒状","kp":""}],"toc":[{"title":"一、蛋白质三维结构概述","pages":"PPT 1—7","start":0,"end":7,"items":[{"title":"弱作用力、肽键平面、Ramachandran图","start":0,"end":7}]},{"title":"二、测定蛋白质三维结构的方法","pages":"PPT 8—14","start":7,"end":14,"items":[{"title":"X射线、NMR、CD、冷冻电镜","start":7,"end":14}]},{"title":"三、蛋白质的二级结构","pages":"PPT 15—28","start":14,"end":28,"items":[{"title":"α螺旋、β折叠、转角、无规卷曲","start":14,"end":28}]},{"title":"四、纤维状蛋白质","pages":"PPT 29—45","start":28,"end":45,"items":[{"title":"α-角蛋白、丝心蛋白、胶原蛋白、弹性蛋白","start":28,"end":45}]},{"title":"五、超二级结构和结构域","pages":"AI 1页","start":45,"end":46,"items":[{"title":"motif与domain","start":45,"end":46}]},{"title":"六、球状蛋白质与三级结构","pages":"AI 1页","start":46,"end":47,"items":[{"title":"疏水核心、结构域、活性位点","start":46,"end":47}]},{"title":"七、膜蛋白的结构","pages":"AI 1页","start":47,"end":48,"items":[{"title":"跨膜α螺旋/β桶","start":47,"end":48}]},{"title":"八、四级结构和亚基缔合","pages":"AI 1页","start":48,"end":49,"items":[{"title":"亚基、对称性、别构","start":48,"end":49}]},{"title":"九、变性、折叠和结构预测","pages":"AI 2页","start":49,"end":51,"items":[{"title":"变性/复性、折叠、预测","start":49,"end":51}]},{"title":"AI图解：第5–9节","pages":"6页","start":51,"end":57,"items":[{"title":"结构域/球状/膜/四级/变性/折叠","start":51,"end":57}]},{"title":"公式与方程式总表","pages":"1页","start":57,"end":58,"items":[{"title":"Bragg/螺旋/β/热力学","start":57,"end":58}]},{"title":"课后习题精解","pages":"7页","start":58,"end":65,"items":[{"title":"索引+Q1/Q2/Q7+Q4/Q9+Q12/Q13","start":58,"end":65}]},{"title":"过程版与实验设计","pages":"4页","start":65,"end":69,"items":[{"title":"Bragg、螺旋参数、纤维识别、方法选择","start":65,"end":69}]},{"title":"原书页扫描","pages":"6页","start":69,"end":75,"items":[{"title":"结构域/球状/膜/四级/变性/Anfinsen","start":69,"end":75}]},{"title":"原书单图卡片","pages":"5页","start":75,"end":80,"items":[{"title":"结构域/溶菌酶/血型糖蛋白/变性/RNase复性","start":75,"end":80}]},{"title":"第3章相关反应式","pages":"1页","start":80,"end":81,"items":[{"title":"二硫键/胶原交联/肽键","start":80,"end":81}]},{"title":"使用评估","pages":"1页","start":81,"end":82,"items":[{"title":"bc03评估与建议","start":81,"end":82}]}]};